import{E as e,d as t,l as n}from"./runtime-core.esm-bundler-BVtXrkU4.js";import{t as r}from"./app-DvxCNKUe.js";var i=JSON.parse(`{"path":"/%E8%AF%AD%E8%A8%80/%E8%8B%B1%E8%AF%AD/Friends%E8%80%81%E5%8F%8B%E8%AE%B0/S09/S09E23.html","title":"S09E23 The One in Barbados","lang":"zh-CN","frontmatter":{"title":"S09E23 The One in Barbados","pageClass":"friends-page","category":["英语"],"tag":["Friends老友记"],"order":217},"git":{"createdTime":1780654155000,"updatedTime":1780654155000,"contributors":[{"name":"jackie.liu","username":"","email":"moklgy@foxmail.com","commits":1}]},"readingTime":{"minutes":70.27,"words":21082},"filePathRelative":"语言/英语/Friends老友记/S09/S09E23.md"}`),a={name:`S09E23.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="the-one-in-barbados" tabindex="-1"><a class="header-anchor" href="#the-one-in-barbados"><span>The One in Barbados</span></a></h1><blockquote><p><em>巴巴多斯的一个</em></p></blockquote><p>923 - 924 - The one in Barbados<br> Part 1 written by: Shana Goldberg-Meehan &amp; Scott Silveri</p><blockquote><p>第1部分作者：沙娜·戈德伯格·米汉和斯科特·西尔维尼</p></blockquote><p>Part 2 written by: Marta Kauffman &amp; David Crane</p><blockquote><p>第2部分作者：玛尔塔·考夫曼和大卫·克雷恩</p></blockquote><p><strong>Directed by: Kevin S. Bright</strong></p><blockquote><p>导演：凯文·S·布莱特</p></blockquote><p><strong>Transcribed by: Andreina, Eleonora, Pheeboh, Sebastiano &amp; Vanessa</strong></p><blockquote><p>转录人：Andreina、Eleonora、Pheeboh、Sebastiano和Vanessa</p></blockquote><hr><p>🎬 <em>Central Perk</em></p><blockquote><p>🎬 <em>中央公园</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (entering) Hey! I&#39;m all packed and ready to go!</p><blockquote><p>（进来）嘿！我都收拾好了，准备出发了！</p></blockquote><p><strong>Ross Geller:</strong> Oh, that&#39;s right! (to Emma) Daddy and uncle Joey are going on a trip today. We&#39;re going to a conference in Barbados, right?</p><blockquote><p>哦，没错！（对艾玛）爸爸和乔伊叔叔今天要去旅行。我们要去巴巴多斯参加一个会议，对吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Mmh-mmh.</p><blockquote><p>嗯。</p></blockquote><p><strong>Ross Geller:</strong> (to Emma) Can you say Barbados?</p><blockquote><p>（对艾玛）你能说巴巴多斯吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Barbados!</p><blockquote><p>巴巴多斯！</p></blockquote><p><strong>Ross Geller:</strong> Ok, I gotta say. I mean, it means so much to me that you guys are coming all the way over there to hear me do my speech! UH! And I&#39;ve a surprise, uh... I had to pull some strings but I was able to get everyone passes to the entire conference! That&#39;s right! (he gives them their passes) This babies will get you into all the paleontology lectures and seminars.</p><blockquote><p>好吧，我得说。我的意思是，这对我意义重大，你们大老远跑过来听我演讲！UH我有个惊喜，呃。。。我不得不拉一些绳子，但我能让每个人都通过整个会议！这是正确的！（他给他们通行证）这些婴儿会让你参加所有的古生物学讲座和研讨会。</p></blockquote><p><strong>Rachel Green:</strong> Do you have anything that would... get us out of them?</p><blockquote><p>你有什么可以。。。让我们离开他们？</p></blockquote><p><strong>Chandler Bing:</strong> Yeah Ross, I mean... we&#39;re excited to hear the speech but the rest of the time we&#39;re gonna wanna do, you know, &quot;island&#39;s stuff&quot;.</p><blockquote><p>是的，罗斯，我是说。。。我们很高兴听到这个演讲，但剩下的时间我们会想做的，你知道，“岛上的东西”。</p></blockquote><p><strong>Phoebe Buffay:</strong> I think David would probably wanna hear a few lectures.</p><blockquote><p>我想大卫可能想听一些讲座。</p></blockquote><p><strong>Ross Geller:</strong> Oh, right, because he&#39;s a scientist!</p><blockquote><p>哦，对了，因为他是个科学家！</p></blockquote><p><strong>Phoebe Buffay:</strong> No, no, because, you know, he&#39;s been in Minsk for 8 years and if he gets too much direct sunlight, he&#39;ll die.</p><blockquote><p>不，不，因为，你知道，他在明斯克已经8年了，如果阳光太直射，他会死的。</p></blockquote><p><strong>Ross Geller:</strong> Ok, we gotta go, yeah? So, we&#39;ll see you guys tomorrow.</p><blockquote><p>好吧，我们得走了，是吗？明天见。</p></blockquote><p><strong>Joey Tribbiani:</strong> All right, let&#39;s do it! 5 hour flight with Charlie, have a couple of drinks, get under that blanket and do what comes naturally.</p><blockquote><p>好吧，我们开始吧！和查理坐5个小时的飞机，喝几杯，躲在毯子下面，做自然发生的事。</p></blockquote><p><strong>Ross Geller:</strong> It&#39;s a blanket Joe, not a cloak of invisibility!</p><blockquote><p>乔，这是毯子，不是隐形斗篷！</p></blockquote><p>Opening credits</p><blockquote><p>期初学分</p></blockquote><hr><p>🎬 <em>Paradise Hotel lounge in Barbados</em></p><blockquote><p>🎬 <em>巴巴多斯天堂酒店酒廊</em></p></blockquote><p><strong>Charlie:</strong> Wow! This place is beautiful!</p><blockquote><p>哇！这地方真漂亮！</p></blockquote><p><strong>Ross Geller:</strong> (very excited) Look at all these paleontologists!!</p><blockquote><p>（非常兴奋）看看这些古生物学家！！</p></blockquote><p><strong>Joey Tribbiani:</strong> I know, there are gonna be some pasty folks by the pool tomorrow! (A woman goes towards them)</p><blockquote><p>我知道，明天游泳池旁边会有一些面团！（一个女人走向他们）</p></blockquote><p><strong>Woman:</strong> Oh my God, I can&#39;t believe you&#39;re here!</p><blockquote><p>哦，我的天，我真不敢相信你在这里！</p></blockquote><p><strong>Joey Tribbiani:</strong> (to Charlie) I think I&#39;ve been recognized, this happens all the time!</p><blockquote><p>（对查理）我想我已经被认出来了，这种事经常发生！</p></blockquote><p><strong>Woman:</strong> Doctor Geller, I&#39;m such a huge fan!</p><blockquote><p>盖勒医生，我是个超级粉丝！</p></blockquote><p><strong>Joey Tribbiani:</strong> That... never happens...</p><blockquote><p>那。。。永远不会发生。。。</p></blockquote><p><strong>Woman:</strong> I&#39;ve been following your career for years, I-I can&#39;t wait for your keynote speech.</p><blockquote><p>我已经关注你的职业生涯很多年了，我等不及你的主题演讲了。</p></blockquote><p><strong>Ross Geller:</strong> Wow! This is very flattering, uh...</p><blockquote><p>哇！这是非常恭维的，嗯。。。</p></blockquote><p><strong>Woman:</strong> I would love your autograph. (hands him a notepad)</p><blockquote><p>我很喜欢你的签名。（递给他一个记事本）</p></blockquote><p><strong>Ross Geller:</strong> Uh, uh... Sure! Uhm... &quot;Dear...&quot; (he takes the notepad)</p><blockquote><p>嗯，嗯。。。当然嗯。。。“亲爱的……”（他拿起记事本）</p></blockquote><p><strong>Woman:</strong> Sarah.</p><blockquote><p>莎拉。</p></blockquote><p><strong>Ross Geller:</strong> &quot;... Sarah. I dig you&quot;, Uh? &quot;Doctor Ross Geller&quot;.</p><blockquote><p>“……莎拉，我喜欢你”，嗯？“罗斯·盖勒医生”。</p></blockquote><p><strong>Sarah:</strong> Thank you so much!</p><blockquote><p>非常感谢你！</p></blockquote><p><strong>Ross Geller:</strong> Yeah, oh and Sarah... I&#39;d like to introduce you to my colleague, uh, Professor Wheeler, a-and this is Joey Tribbiani.</p><blockquote><p>是的，哦，还有莎拉。。。我想把你介绍给我的同事，呃，惠勒教授，这位是乔伊·特里比亚尼。</p></blockquote><p><strong>Sarah:</strong> (to Joey) Are you a paleontologist?</p><blockquote><p>（对乔伊）你是古生物学家吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> No, God, no! No! No no, I&#39;m an actor. You&#39;d probably recognize me from a little show called &quot;The Days of Our Lives&quot;.</p><blockquote><p>不，上帝，不！不不，不，我是演员。你可能会从一个叫做“我们生活的日子”的小节目中认出我来。</p></blockquote><p><strong>Ross Geller:</strong> Dude, it&#39;s just &quot;Days of Our Lives&quot;... there&#39;s no the.</p><blockquote><p>伙计，这只是“我们生命中的日子”。。。没有什么好消息。</p></blockquote><p><strong>Joey Tribbiani:</strong> (thinking he&#39;s kidding) Ok, Ross! It&#39;s... It&#39;s fun, yeah! No, I-I play Doctor Drake Ramoray.</p><blockquote><p>（以为他在开玩笑）好吧，罗斯！是。。。很有趣，是的！不，我扮演Drake Ramoray医生。</p></blockquote><p><strong>Sarah:</strong> I&#39;m sorry, I don&#39;t own a TV.</p><blockquote><p>对不起，我没有电视。</p></blockquote><p><strong>Joey Tribbiani:</strong> You don&#39;t own a TV? What&#39;s all your furniture pointed at??</p><blockquote><p>你没有电视吗？你所有的家具都指向什么？？</p></blockquote><hr><p>🎬 <em>Central Perk</em></p><blockquote><p>🎬 <em>中央公园</em></p></blockquote><p><strong>Monica Geller:</strong> David, can you help me?! I&#39;m trying to explain to Chandler how a plane stays in the air.</p><blockquote><p>大卫，你能帮我吗？！我想向钱德勒解释飞机是如何在空中飞行的。</p></blockquote><p><strong>David:</strong> Oh, certainly. That&#39;s a combination of Bernoulli&#39;s principle and Newton&#39;s third law of motion.</p><blockquote><p>哦，当然可以。这是伯努利原理和牛顿第三运动定律的结合。</p></blockquote><p><strong>Monica Geller:</strong> (to Chandler) See?</p><blockquote><p>（对钱德勒）看到了吗？</p></blockquote><p><strong>Chandler Bing:</strong> Yeah, that&#39;s the same as &quot;it has something to do with wind&quot;.</p><blockquote><p>是的，这和“它和风有关”是一样的。</p></blockquote><p><strong>Monica Geller:</strong> Alright, I&#39;m gonna go pick up a few things for the trip.</p><blockquote><p>好吧，我要去买些旅行用的东西。</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, I should go, too. Oh, now... tomorrow do you guys wanna share a cab to the airport or should Mike and I just meet you there.</p><blockquote><p>哦，我也应该去。哦，现在。。。明天你们是想坐出租车去机场，还是迈克和我就在那里等你们。</p></blockquote><p><em>(Everyone looks at her)</em></p><blockquote><p><em>（每个人都看着她）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Mike?? Who&#39;s Mike?</p><blockquote><p>迈克？？迈克是谁？</p></blockquote><p><strong>David:</strong> Mike is your ex... uh... boyfriend!</p><blockquote><p>迈克是你的前任。。。UH男朋友！</p></blockquote><p><strong>Phoebe Buffay:</strong> That&#39;s right! Oh, yeah... Well, I&#39;ve totally forgotten about im! AH! That&#39;s-That&#39;s... a blast from the past!</p><blockquote><p>没错！哦，是的。。。嗯，我已经完全忘记im了！啊!！那是，那是。。。过去的爆炸！</p></blockquote><p><strong>David:</strong> It&#39;s ok. Ho-honest mistake.</p><blockquote><p>没关系。他犯了一个诚实的错误。</p></blockquote><p><strong>Phoebe Buffay:</strong> Really, it doesn&#39;t mean anything. I mean, you know, Monica refers to Chandler as Richard all the time!</p><blockquote><p>真的，这没有任何意义。我是说，你知道，莫妮卡总是把钱德勒称为理查德！</p></blockquote><p><strong>Chandler Bing:</strong> (upset) She does?</p><blockquote><p>（心烦意乱）是吗？</p></blockquote><p><strong>Monica Geller:</strong> (pinching her) Let&#39;s get you out of here!! (they go outside)</p><blockquote><p>（捏她）让我们带你离开这里！！（他们出去了）</p></blockquote><p><em>(Outside the Central Perk)</em></p><blockquote><p><em>（中央公园外）</em></p></blockquote><p><strong>Monica Geller:</strong> At least you took me down with you!</p><blockquote><p>至少你把我和你一起带走了！</p></blockquote><p><strong>Phoebe Buffay:</strong> I&#39;m sooo sorry!! I just... I keep thinking about Mike! I&#39;m crazy about David, and we&#39;re having so much fun together. Why-Why do I miss Mike? That&#39;s-that&#39;s gonna go away, right?</p><blockquote><p>我很抱歉！！我只是。。。我一直在想迈克！我很喜欢大卫，我们在一起玩得很开心。为什么我会想念迈克？那会过去的，对吧？</p></blockquote><p><strong>Monica Geller:</strong> I guess, in time.</p><blockquote><p>我想，是时候了。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Monica Geller:</strong> I mean, my feelings for Richard are certainly gone.</p><blockquote><p>我的意思是，我对理查德的感情肯定消失了。</p></blockquote><p><strong>Phoebe Buffay:</strong> You just did it again. Chandler, your feelings for Chandler are certainly gone!</p><blockquote><p>你又做了一次。钱德勒，你对钱德勒的感情真的消失了！</p></blockquote><hr><p>🎬 <em>Inside Central Perk</em></p><blockquote><p>🎬 <em>中央公园内</em></p></blockquote><p><strong>David:</strong> (to Chandler) Well, Phoebe&#39;s still pretty hung up on that Mike, uh?</p><blockquote><p>（对钱德勒）嗯，菲比还是很喜欢那个麦克，嗯？</p></blockquote><p><strong>Chandler Bing:</strong> I wouldn&#39;t read too much into it.</p><blockquote><p>我不会读太多。</p></blockquote><p><strong>David:</strong> Still you know, a girl calls you by your ex-boyfriend&#39;s name, that-that&#39;s not a good thing, right?</p><blockquote><p>你还是知道，一个女孩叫你前男友的名字，那不是件好事，对吧？</p></blockquote><p><strong>Chandler Bing:</strong> David, let me stop you there &#39;cause I think I see where this is going. I&#39;m not very good at giving advice. So if you want advice, go to Ross, Monica, or... Joey, if the thing you wanna advice about is pizza toppings or burning sensation when you pee.</p><blockquote><p>大卫，让我阻止你，因为我想我知道这是怎么回事。我不太擅长提建议。如果你想得到建议，去找罗斯，莫妮卡，或者。。。乔伊，如果你想建议的是披萨配料或者小便时的灼热感。</p></blockquote><p><strong>David:</strong> Sorry, I just... I wish there was something I could do, you know? Well, you know Phoebe...</p><blockquote><p>对不起，我只是。。。我希望我能做点什么，你知道吗？嗯，你知道菲比。。。</p></blockquote><p><strong>Chandler Bing:</strong> Seriously, we&#39;re gonna do this?</p><blockquote><p>说真的，我们要这么做？</p></blockquote><p><strong>David:</strong> I&#39;m sorry, uh... I just wish I could make her forget about Mike already, you know... Why did Phoebe and Mike break up?</p><blockquote><p>对不起，呃。。。我只是希望我能让她忘记迈克，你知道。。。为什么菲比和迈克分手了？</p></blockquote><p><strong>Chandler Bing:</strong> Oh, because his penis was too big. (he notices that David is not amused) Oh, I&#39;m sorry, that&#39;s the kind of thing I do. (pause) They broke up because Mike didn&#39;t want to get married. Hey, what if you just let Phoebe know you&#39;d be open to marriage?</p><blockquote><p>哦，因为他的阴茎太大了。（他注意到大卫并不开心）哦，对不起，我就是这么做的。（停顿）他们分手是因为迈克不想结婚。嘿，如果你让菲比知道你愿意结婚呢？</p></blockquote><p><strong>David:</strong> That&#39;s great! That&#39;s great! I-I&#39;ll propose to her!</p><blockquote><p>太好了！太好了！我要向她求婚！</p></blockquote><p><strong>Chandler Bing:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>David:</strong> Well, I was probably going to do it at some point.</p><blockquote><p>嗯，我可能会在某个时候这样做。</p></blockquote><p><strong>Chandler Bing:</strong> I didn&#39;t mean now...</p><blockquote><p>我不是说现在。。。</p></blockquote><p><strong>David:</strong> Why not? It&#39;s brilliant! (talking to an imaginary Mike) Goodbye Mike, we&#39;ll see you at the wedding, fella! (pause) well, we probably won&#39;t invite you to the wedding... (to Chandler) Thank you, Chandler. Sincerely.</p><blockquote><p>为什么不呢？太棒了！（对一个想象中的迈克说）再见，迈克，我们在婚礼上见，伙计！（停顿）嗯，我们可能不会邀请你参加婚礼。。。（对钱德勒）谢谢你，钱德勒。真诚地</p></blockquote><p><strong>Chandler Bing:</strong> Well, you&#39;re welcome! Glad I could help.</p><blockquote><p>不客气！很高兴我能帮忙。</p></blockquote><p><strong>David:</strong> (after a while) How do you think I should propose?</p><blockquote><p>（过了一会儿）你觉得我该怎么求婚？</p></blockquote><p><strong>Chandler Bing:</strong> David, I&#39;m pretending to read here!!</p><blockquote><p>大卫，我在这里假装看书！！</p></blockquote><hr><p>🎬 <em>Joey in his hotel in room in Barbados</em></p><blockquote><p>🎬 <em>乔伊在巴巴多斯的酒店房间里</em></p></blockquote><p><em>(Trying on a hat and talking to his own reflection in the mirror)</em></p><blockquote><p><em>（试戴帽子，对着镜子里自己的倒影说话）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah! How you doin&#39;? Yeah alright!</p><blockquote><p>是啊！你好吗？是的，好吧！</p></blockquote><p><em>(Charlie comes out the bathroom)</em></p><blockquote><p><em>（查理从浴室出来）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, hey! You said you&#39;re gonna wear a thong, where&#39;s the thong?</p><blockquote><p>嘿，嘿！你说你要穿丁字裤，丁字裤在哪里？</p></blockquote><p><strong>Charlie:</strong> (laughing) I didn&#39;t mean a thong... I meant thongs...</p><blockquote><p>（笑）我不是指皮带。。。我是说丁字裤。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> You really should have been more clear about that!</p><blockquote><p>你真的应该更清楚这一点！</p></blockquote><p><em>(Someone knocks the door, Joey goes to open it and Ross is on the other side)</em></p><blockquote><p><em>（有人敲门，乔伊去开门，罗斯在另一边）</em></p></blockquote><p><strong>Ross Geller:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><strong>Ross Geller:</strong> (Excited) You&#39;re never going to guess who I just saw downstairs!</p><blockquote><p>（激动地）你永远猜不到我刚才在楼下看见了谁！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh! ah! eh... Britney Spears!?</p><blockquote><p>哦！啊!！嗯。。。布兰妮·斯皮尔斯！？</p></blockquote><p><strong>Ross Geller:</strong> Yeah, she never misses these conferences! (then to Charlie) No, I just saw Dr. Kenneth Schwartz!</p><blockquote><p>是啊，她从不错过这些会议！（然后对查理说）不，我刚见到肯尼斯·施瓦茨博士！</p></blockquote><p><strong>Charlie:</strong> Oh my God! Did you talk to him?</p><blockquote><p>天哪！你和他谈过了吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah... what am I going to say to Kenneth Schwartz?</p><blockquote><p>是的。。。我要对肯尼斯·施瓦茨说什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> You could say: &quot;Hey Kenny, how come you&#39;re not Britney Spears?&quot; (looks at Ross matter-of-factly)</p><blockquote><p>你可以说：“嘿，肯尼，你怎么不是小甜甜布兰妮？”（实事求是地看着罗斯）</p></blockquote><p><strong>Ross Geller:</strong> (to Charlie) Ready to go?</p><blockquote><p>（对查理）准备好出发了吗？</p></blockquote><p><strong>Charlie:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Joey Tribbiani:</strong> Wha...? You&#39;re gonna go now? I thought we could hang out?</p><blockquote><p>什么。。。？你现在要走了？我以为我们可以出去玩？</p></blockquote><p><strong>Charlie:</strong> Oh I can&#39;t... I have seminars all day and I promised Ross I would look at his speech.</p><blockquote><p>哦，我不能。。。我整天都在开研讨会，我答应罗斯我会看他的演讲。</p></blockquote><p><strong>Ross Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Charlie:</strong> But maybe we can have dinner later? On the balcony? Will be romantic.</p><blockquote><p>但也许我们可以晚一点吃晚饭？在阳台上？会很浪漫。</p></blockquote><p><strong>Joey Tribbiani:</strong> (smiling) Will you wear a thong?</p><blockquote><p>（微笑）你会穿丁字裤吗？</p></blockquote><p><strong>Charlie:</strong> I will if you will.</p><blockquote><p>如果你愿意，我会的。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh... you got yourself a very weird deal!</p><blockquote><p>哦。。。你做了一笔很奇怪的交易！</p></blockquote><p><strong>Ross Geller:</strong> (a little embarassed by their conversation) I&#39;m good, I have dinner plans (moves away from them).</p><blockquote><p>（被他们的谈话弄得有点尴尬）我很好，我有晚餐计划（离开他们）。</p></blockquote><p><strong>Charlie:</strong> So you&#39;ll be ok?</p><blockquote><p>那么你没事了？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, yeah. I&#39;ve got tons of stuff I could do. I&#39;m gonna hit the beach, go swimming...</p><blockquote><p>是的，是的。我有很多事情可以做。我要去海滩游泳。。。</p></blockquote><p><strong>Ross Geller:</strong> Uh, Joe, have you looked outside?</p><blockquote><p>呃，乔，你看过外面吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> No, why?</p><blockquote><p>没有，为什么？</p></blockquote><p><em>(Ross goes to the window and opens the curtains revealing that it&#39;s raining outside)</em></p><blockquote><p><em>（罗斯走到窗前，拉开窗帘，露出外面在下雨。）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Oh man!</p><blockquote><p>哦，老兄！</p></blockquote><p><strong>Charlie:</strong> There&#39;s an indoor pool, you can swim there! (Ross agrees)</p><blockquote><p>有一个室内游泳池，你可以在那里游泳！（罗斯同意）</p></blockquote><p><strong>Joey Tribbiani:</strong> I wasn&#39;t gonna swim, I was gonna dig a hole! (removes a small plastic spade used by children to play on the beach from his backpack)</p><blockquote><p>我不是要游泳，我要挖个洞！（从背包中取出一把小塑料铲，孩子们在沙滩上玩耍时使用）</p></blockquote><hr><p>🎬 <em>Back in New York, Monica and Chandler in Central Perk on the couch</em></p><blockquote><p>🎬 <em>回到纽约，莫妮卡和钱德勒在中央公园的沙发上</em></p></blockquote><p><strong>Monica Geller:</strong> Wow! That Mike thing was interesting! I don&#39;t know what&#39;s gonna happen with Phoebe and David.</p><blockquote><p>哇！迈克的事很有趣！我不知道菲比和大卫会怎么样。</p></blockquote><p><strong>Chandler Bing:</strong> (smiling cheekily) I do! Want a hint? huh? &quot;I do&quot; (Monica looks confused, so Chandler repeats) &quot;I do&quot;.</p><blockquote><p>（厚颜无耻地笑）是的！需要提示吗？呵呵？“我知道”（莫妮卡看起来很困惑，所以钱德勒重复道）“我知道”。</p></blockquote><p><strong>Monica Geller:</strong> Ok, I&#39;m sensing that this is some kind of word play, because you are pink with barely controlled glee.</p><blockquote><p>好吧，我感觉这是一种文字游戏，因为你脸色发红，几乎无法控制自己的喜悦。</p></blockquote><p><strong>Chandler Bing:</strong> David is going to propose to Phoebe.</p><blockquote><p>大卫要向菲比求婚。</p></blockquote><p><strong>Monica Geller:</strong> What? (looks very shocked) Why?</p><blockquote><p>什么？（看起来很震惊）为什么？</p></blockquote><p><strong>Chandler Bing:</strong> Be-cause, we were talking about ways that he could beat Mike and I told him that Phoebe wanted to get married.</p><blockquote><p>因为，我们在讨论他能打败迈克的方法，我告诉他菲比想结婚。</p></blockquote><p><strong>Monica Geller:</strong> Chandler, we have talked about this. You are not supposed to give people advice! Now couldn&#39;t you just have made some sort of inappropriate joke?</p><blockquote><p>钱德勒，我们已经谈过了。你不应该给别人建议！你就不能开个不恰当的玩笑吗？</p></blockquote><p><strong>Chandler Bing:</strong> I did! A penis one! Look, just so I know, what was so wrong about what I said?</p><blockquote><p>是的！一个阴茎！听着，让我知道，我说的有什么不对吗？</p></blockquote><p><strong>Monica Geller:</strong> They&#39;ve only been going out for a few weeks and Phoebe is completely hung up on Mike! She&#39;ll say &quot;No&quot;, David&#39;s heart will be broken, it will be too hard for them to recover from and then Phoebe will end up alone again.</p><blockquote><p>他们只约会了几个星期，菲比完全被迈克挂住了！她会说“不”，大卫的心会碎，他们很难从中恢复过来，然后菲比会再次孤独。</p></blockquote><p><strong>Chandler Bing:</strong> Man, that&#39;s some bad advice!</p><blockquote><p>老兄，这是个糟糕的建议！</p></blockquote><hr><p>🎬 <em>Barbados, hotel lounge. David, Phoebe and Rachel have just arrived.</em></p><blockquote><p>🎬 <em>巴巴多斯，酒店休息室。大卫、菲比和瑞秋刚到。</em></p></blockquote><p><em>(Joey spots them and walks towards them)</em></p><blockquote><p><em>（乔伊发现了他们，朝他们走去）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Oh! Hey! Thank God you guys are here!</p><blockquote><p>哦！嘿感谢上帝你们来了！</p></blockquote><p><strong>Rachel Green:</strong> Hey! Hey what&#39;s going on?</p><blockquote><p>嘿！嘿，发生什么事了？</p></blockquote><p><strong>Joey Tribbiani:</strong> Everything is upside down here! It rains all day long, nobody watches tv and Ross is famous!</p><blockquote><p>这里一切都颠倒了！整天下雨，没人看电视，罗斯很出名！</p></blockquote><p><em>(Rachel turns around and sees Chandler and Monica arriving)</em></p><blockquote><p><em>（瑞秋转过身，看到钱德勒和莫妮卡来了）</em></p></blockquote><p><strong>Rachel Green:</strong> Alright, I don&#39;t wanna alarm anybody, but Monica&#39;s hair is twice as big as it was when we landed!</p><blockquote><p>好吧，我不想惊动任何人，但莫妮卡的头发是我们着陆时的两倍大！</p></blockquote><p><em>(Monica and Chandler reach the group)</em></p><blockquote><p><em>（莫妮卡和钱德勒到达小组）</em></p></blockquote><p><strong>Monica Geller:</strong> Ok! When I go places with high humidity, it gets a little extra body, ok?!</p><blockquote><p>好的！当我去高湿度的地方，它会有一个额外的身体，好吗？！</p></blockquote><p><strong>Chandler Bing:</strong> That&#39;s why our honeymoon photos look like me and Diana Ross!</p><blockquote><p>这就是为什么我们的蜜月照片看起来像我和戴安娜·罗斯！</p></blockquote><p><strong>Joey Tribbiani:</strong> Come on, I&#39;ll show you guys where to check in (Joey, Chandler and David leave)</p><blockquote><p>来吧，我带你们去哪里登记（乔伊、钱德勒和大卫离开）</p></blockquote><p><strong>Monica Geller:</strong> (to Chandler) Oh, honey, can you make sure we get a King size bed!</p><blockquote><p>（对钱德勒）哦，亲爱的，你能保证我们有一张特大号床吗！</p></blockquote><p><strong>Phoebe Buffay:</strong> (shouts after David) Oh! David, get one for us too! Oh, oh, and see if they have a heart-shaped one! And with mirrors on the ceiling!</p><blockquote><p>（跟在大卫后面喊）哦！大卫，也给我们买一个！哦，哦，看看他们有没有心形的！天花板上有镜子！</p></blockquote><p><strong>Monica Geller:</strong> (shouts to Chandler) And make sure our room isn&#39;t next to theirs (points to Phoebe).</p><blockquote><p>（对钱德勒喊道）确保我们的房间不挨着他们的（指着菲比）。</p></blockquote><p><strong>Rachel Green:</strong> Ooh! You guys are so lucky you are here with people, you known it&#39;s such a romantic place. That&#39;s all, I just wish I could (looks at Joey who is at the check in desk) share that with a guy.</p><blockquote><p>哦！你们很幸运能和人们在一起，你们知道这是个浪漫的地方。就这些，我只是希望我能（看着在登记台的乔伊）和一个男人分享。</p></blockquote><p><strong>Phoebe Buffay:</strong> Not Joey.</p><blockquote><p>不是乔伊。</p></blockquote><p><strong>Rachel Green:</strong> Not Joey, no, I was just lusting after Chandler.</p><blockquote><p>不是乔伊，不是，我只是在追求钱德勒。</p></blockquote><p><strong>Monica Geller:</strong> Yeah, right!</p><blockquote><p>是的，对！</p></blockquote><p>[Cut to the guys]</p><blockquote><p>[切到男人们]</p></blockquote><p><strong>David:</strong> So, ehm... I&#39;m proposing to Pheobe tonight. (Removes a ring box from his pocket and opens it to show Chandler the ring)</p><blockquote><p>那么，嗯。。。我今晚要向你求婚。（从钱德勒口袋里拿出一个戒指盒，打开盒子，让钱德勒看戒指）</p></blockquote><p><strong>Chandler Bing:</strong> Tonight?! (looks at the ring) Isn&#39;t an engagement ring supposed to have a diamond? (squints at the ring to emphasize how tiny the diamond is) Oh, there it is!</p><blockquote><p>今晚？！（看着戒指）订婚戒指不应该有钻石吗？（眯着眼睛看戒指，强调钻石有多小）哦，它在那儿！</p></blockquote><p><strong>David:</strong> Yeah, well, being a failed scientist doesn&#39;t pay quite as well as you might think. That&#39;s uhm... one seventieth of a karat. And the clarity is uhm... is quite poor.</p><blockquote><p>是啊，作为一名失败的科学家，报酬并不像你想象的那么高。那是嗯。。。七十分之一克拉。而且清晰度是嗯。。。他很穷。</p></blockquote><p><strong>Chandler Bing:</strong> (slaps him on the shoulder) Nice! (goes to Monica)</p><blockquote><p>（拍拍他的肩膀）很好！（走向莫妮卡）</p></blockquote><p><strong>Chandler Bing:</strong> Monica, can I talk to you for a sec? (Pulls her away from Phoebe and Rachel)</p><blockquote><p>莫妮卡，我能和你谈谈吗？（把她从菲比和瑞秋身边拉开）</p></blockquote><p><strong>Monica Geller:</strong> Ok!</p><blockquote><p>好的！</p></blockquote><p><strong>Chandler Bing:</strong> David is going to propose to Phoebe tonight!</p><blockquote><p>大卫今晚要向菲比求婚！</p></blockquote><p><strong>Monica Geller:</strong> See what happens when you give people advice? I hope you told him not to?</p><blockquote><p>看看当你给别人提建议时会发生什么？我希望你告诉他不要？</p></blockquote><p><strong>Chandler Bing:</strong> That would be advice!!</p><blockquote><p>那是个忠告！！</p></blockquote><p><strong>Monica Geller:</strong> Ok fine. I&#39;ll handle this. (goes to Phoebe who&#39;s talking to Rachel) Phoebe?</p><blockquote><p>好的。我来处理。（走向正在和瑞秋说话的菲比）菲比？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Monica Geller:</strong> (looking very serious) I need to talk to you.</p><blockquote><p>（看起来很严肃）我需要和你谈谈。</p></blockquote><p><strong>Phoebe Buffay:</strong> Are you leaving &quot;The Supremes&quot;? (Monica and Phoebe go to one side)</p><blockquote><p>你要离开《至高无上》吗？（莫妮卡和菲比走到一边）</p></blockquote><p><strong>Monica Geller:</strong> Ok, my husband just gave your boyfriend some very bad advice. Look, David is going to propose to you tonight.</p><blockquote><p>好吧，我丈夫刚刚给了你男朋友一些很糟糕的建议。听着，大卫今晚要向你求婚。</p></blockquote><p><strong>Phoebe Buffay:</strong> Wow? Really? That&#39;s fantastic!</p><blockquote><p>哇？真正地太棒了！</p></blockquote><p><strong>Monica Geller:</strong> What are you serious? You wanna marry him? Wha... What about Mike?</p><blockquote><p>你是认真的吗？你想嫁给他？什么。。。迈克呢？</p></blockquote><p><strong>Phoebe Buffay:</strong> Oh, ok, you want me to marry Mike? Alright, well, let&#39;s just gag him and handcuff him and force him down the aisle. I can just see it: &quot;Mike, do you take Phoebe...&quot; (gestures with her hand as if someone is covering her mouth and tries to shout &quot;No! No!&quot;) You know, it&#39;s every girl&#39;s dream!</p><blockquote><p>哦，好吧，你想让我嫁给迈克？好吧，好吧，让我们把他堵住，铐上手铐，强迫他走下走道。我可以看到：“迈克，你带菲比去吗……”（她用手做手势，好像有人捂住她的嘴，试图喊“不！不！”）你知道，这是每个女孩的梦想！</p></blockquote><p><strong>Monica Geller:</strong> Do you really think marrying someone else is the right answer?</p><blockquote><p>你真的认为和别人结婚是正确的答案吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Sure! Look, ok, bottom line: I love Mike... David! David. I love David. Don&#39;t look at me that way, Roseanne Rosannadanna!</p><blockquote><p>当然！听着，好吧，底线是：我爱迈克。。。大卫！大卫。我爱大卫。别那样看我，罗莎妮·罗莎娜·丹娜！</p></blockquote><hr><p>🎬 <em>Ross&#39;s hotel room. Ross and is reading his keynote speech to Charlie from his laptop</em></p><blockquote><p>🎬 <em>罗斯的酒店房间。罗斯正在笔记本电脑上读他对查理的主题演讲</em></p></blockquote><p><strong>Ross Geller:</strong> By using CT scans and computer imaging we can in a very real way, bring the Mesozoic era into the 21st century.</p><blockquote><p>通过CT扫描和计算机成像，我们可以非常真实地将中生代带入21世纪。</p></blockquote><p><strong>Charlie:</strong> It&#39;s great. You&#39;re gonna be the hit of the conference.</p><blockquote><p>太棒了。你会成为这次会议的热门人物。</p></blockquote><p><strong>Ross Geller:</strong> Oh and you know what, it will be even better tomorrow, because I won&#39;t be constantly interrupted by Joey checking to see if they put chocolates on my pillow yet. (Someone knocks on the door, Ross goes to open and it&#39;s Joey, Rachel and Chandler).</p><blockquote><p>哦，你知道吗，明天会更好，因为我不会经常被乔伊打搅，看看他们有没有把巧克力放在我的枕头上。（有人敲门，罗斯开门，是乔伊、瑞秋和钱德勒）。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey guys!</p><blockquote><p>嘿，伙计们！</p></blockquote><p><strong>Ross Geller:</strong> The chocolates aren&#39;t here yet.</p><blockquote><p>巧克力还没到呢。</p></blockquote><p><strong>Joey Tribbiani:</strong> Damnit!</p><blockquote><p>该死！</p></blockquote><p><strong>Charlie:</strong> Ross just read me his speech. It&#39;s fantastic!</p><blockquote><p>罗斯刚刚给我读了他的演讲稿。太棒了！</p></blockquote><p><strong>Chandler Bing:</strong> Oh, is it on the computer, cuz I&#39;d love to give it a read...?</p><blockquote><p>哦，它在电脑上吗，因为我想看一下。。。？</p></blockquote><p><strong>Ross Geller:</strong> If you want to check your email, just ask! (Chandler tries to look offended)</p><blockquote><p>如果你想查看你的电子邮件，就问吧！（钱德勒试图装出生气的样子）</p></blockquote><p><strong>Chandler Bing:</strong> (offended) What? (pause) May I?</p><blockquote><p>（生气）什么？（停顿）我可以吗？</p></blockquote><p><strong>Rachel Green:</strong> (looking out the window) What&#39;s with the rain, Geller? I mean, when I signed up for Dino Week, nobody said anything about it being monsoon season.</p><blockquote><p>（看着窗外）雨怎么了，盖勒？我是说，当我报名参加恐龙周时，没有人说这是季风季节。</p></blockquote><p><strong>Charlie:</strong> Actually the wet season is June to December.</p><blockquote><p>实际上雨季是六月到十二月。</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s not the time Charlie.</p><blockquote><p>查理，现在不是时候。</p></blockquote><p><strong>Chandler Bing:</strong> (at the laptop) Oh, no, no, no dear God, no!</p><blockquote><p>（对着笔记本电脑）哦，不，不，不，天哪，不！</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh what, did someone outbid you for the teapot? (Chandler looks annoyed at him and Joey leans in to him) Oh! Secret teapot?</p><blockquote><p>哦，怎么了，有人出价比你高吗？（钱德勒生气地看着他，乔伊靠在他身上）哦！秘密茶壶？</p></blockquote><p><strong>Chandler Bing:</strong> Your computer, I don&#39;t know wha... everything&#39;s gone!</p><blockquote><p>你的电脑，我不知道。。。一切都不见了！</p></blockquote><p><strong>Ross Geller:</strong> Wha... what do you mean? (Goes to the laptop)</p><blockquote><p>什么。。。什么意思？（转到笔记本电脑）</p></blockquote><p><strong>Chandler Bing:</strong> It must be a virus. I think it erased your hard drive.</p><blockquote><p>一定是病毒。我想它擦掉了你的硬盘。</p></blockquote><p><strong>Ross Geller:</strong> What, oh my God. What did you do?</p><blockquote><p>什么，我的天啊。你做了什么？</p></blockquote><p><strong>Chandler Bing:</strong> Someone I don&#39;t know sent me an e-mail and I opened it.</p><blockquote><p>一个我不认识的人给我发了一封电子邮件，我打开了。</p></blockquote><p><strong>Ross Geller:</strong> Why, why would you open it?</p><blockquote><p>为什么，你为什么要打开它？</p></blockquote><p><strong>Chandler Bing:</strong> Well, it didn&#39;t say &quot;This is a virus&quot;!!</p><blockquote><p>嗯，它没有说“这是一种病毒”！！</p></blockquote><p><strong>Ross Geller:</strong> What did it say?</p><blockquote><p>上面说什么？</p></blockquote><p><strong>Chandler Bing:</strong> Nude... (Ross looks at him)... pictures of Anna Kournikova. I&#39;m so sorry.</p><blockquote><p>裸体。。。（罗斯看着他）。。。安娜·库尔尼科娃的照片。我很抱歉。</p></blockquote><p><strong>Ross Geller:</strong> What... what am I gonna do? My speech is gone, Chandler!</p><blockquote><p>什么。。。我该怎么办？我的演讲完了，钱德勒！</p></blockquote><p><strong>Chandler Bing:</strong> It&#39;s not gone! I mean, I&#39;m sure you printed out a copy. You have a hard copy, right?</p><blockquote><p>它还没走！我是说，我肯定你打印了一份。你有硬拷贝，对吗？</p></blockquote><p><strong>Ross Geller:</strong> NO! I don&#39;t!!</p><blockquote><p>不！我不！！</p></blockquote><p><strong>Chandler Bing:</strong> Well, you must be pretty mad at yourself right now...!</p><blockquote><p>嗯，你现在一定很生自己的气。。。！</p></blockquote><p>⏱ <em>Time lapse: Ross looks likes he&#39;s been trying to fix his computer but just closes it as if giving up</em></p><blockquote><p>[时间流逝：罗斯看起来好像一直在试图修复他的电脑，但他只是关闭它，好像放弃了]</p></blockquote><p><strong>Joey Tribbiani:</strong> It&#39;s really gone?</p><blockquote><p>真的不见了？</p></blockquote><p><strong>Ross Geller:</strong> Yep! I&#39;d like to thank you guys for coming down here to complain about the rain and ruin my career!</p><blockquote><p>是的！我要感谢你们来到这里抱怨下雨，毁了我的事业！</p></blockquote><p><strong>Chandler Bing:</strong> I just feel awful.</p><blockquote><p>我只是觉得很糟糕。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, well you should! I mean, nude pictures of Anna Kournikova? I mean, she&#39;s never even won a major tournament!</p><blockquote><p>是啊，你应该这么做！我是说安娜·库尔尼科娃的裸照？我的意思是，她甚至从未赢得过大赛！</p></blockquote><p><strong>Chandler Bing:</strong> Well, I tried Billy Jean King, but... (Ross glares at him) you know, you and Monica have the same &quot;I&#39;m gonna kill you&quot; look...? I can usually make it go away by kissing her... (Ross continues to glare at him and Chandler leans in as if he&#39;s going to kiss Ross)</p><blockquote><p>我试过比利·金，但是。。。（罗斯瞪了他一眼）你知道吗，你和莫妮卡有着同样的“我要杀了你”看。。。？我通常可以通过吻她让它消失。。。（罗斯继续瞪着他，钱德勒斜靠着，好像要吻罗斯）</p></blockquote><p><strong>Ross Geller:</strong> Get out! (Chandler runs out)</p><blockquote><p>出去！（钱德勒跑了出去）</p></blockquote><p><strong>Rachel Green:</strong> You know, this happens all the time to my computer at work.</p><blockquote><p>你知道，我工作时的电脑总是这样。</p></blockquote><p><strong>Ross Geller:</strong> Well, what do you do?</p><blockquote><p>嗯，你是做什么的？</p></blockquote><p><strong>Rachel Green:</strong> Well, I usually go... play Tetris on somebody else&#39;s computer.</p><blockquote><p>嗯，我通常去。。。在别人的电脑上玩俄罗斯方块。</p></blockquote><p><strong>Ross Geller:</strong> I can&#39;t believe this. I can&#39;t believe this is happening. I have to give the keynote speech tomorrow! Ok? I have to stand up in front of all these people. What am I gonna say?</p><blockquote><p>我真不敢相信。我真不敢相信这会发生。我明天要做主题演讲！好啊我必须站在所有这些人面前。我该怎么说？</p></blockquote><p><strong>Joey Tribbiani:</strong> I could teach you a speech that I memorized for auditions.</p><blockquote><p>我可以教你一个我在试镜时背下来的演讲。</p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t think that your monologue from Star Wars is gonna help me right now, Joe!</p><blockquote><p>乔，我认为你在《星球大战》中的独白现在对我没有帮助！</p></blockquote><p><strong>Charlie:</strong> Ross, we can solve this. I just heard your speech. We can recreate it! We&#39;ve got all night!</p><blockquote><p>罗斯，我们可以解决这个问题。我刚听了你的演讲。我们可以重新创造它！我们有一整晚的时间！</p></blockquote><p><strong>Ross Geller:</strong> Wha... what you really think we can do that?</p><blockquote><p>什么。。。你认为我们能做到什么？</p></blockquote><p><strong>Charlie:</strong> Oh wait, Joey and I are supposed to have dinner (Looks at Joey).</p><blockquote><p>哦，等等，乔伊和我应该吃晚饭（看着乔伊）。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey don&#39;t worry about that! I mean, Ross needs you! And Rachel and I will stay and help anyway we can.</p><blockquote><p>嘿，别担心！我是说，罗斯需要你！瑞秋和我会留下来，尽我们所能帮助你。</p></blockquote><p><strong>Rachel Green:</strong> Ugh.</p><blockquote><p>啊。</p></blockquote><p><strong>Ross Geller:</strong> Alright, ok, let&#39;s do it. (Ross sits down at the desk and they all gather around him) Uhm, I know we start by discussing the shortcomings of carbon dating... uhm, and then, then I move on to what is clearly the defining moment of the Mesozoic era, the breakup of Pangea, hello! (Rachel and Joey look confused) And then, there&#39;s the... eh... there&#39;s the overview of the Triassic.</p><blockquote><p>好吧，好吧，我们开始吧。（罗斯坐在办公桌旁，他们都围在他身边）嗯，我知道我们从讨论碳年代测定的缺点开始。。。嗯，然后，我继续讨论中生代的决定性时刻，盘古大陆的解体，您好！（瑞秋和乔伊看起来很困惑）然后，是。。。嗯。。。这是三叠纪的概况。</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, oh! Any chance any of this happened in a &quot;Galaxy far, far away&quot;? (Ross turns aroud and glares at him. Joey and Rachel decide to leave).</p><blockquote><p>哦，哦！这一切有没有可能发生在“遥远的星系”？（罗斯转过身来瞪着他。乔伊和瑞秋决定离开）。</p></blockquote><hr><p>🎬 <em>Mike&#39;s apartment. His phone rings and he picks up</em></p><blockquote><p>🎬 <em>迈克的公寓。他的电话响了，他拿起了电话</em></p></blockquote><p><strong>Mike:</strong> Hello?</p><blockquote><p>喂？</p></blockquote><p><strong>Monica Geller:</strong> Ok, Mike, enough is enough, now you love Phoebe and she loves you, so you need to get over your whole &quot;I never want to get married&quot; thing and step up!</p><blockquote><p>好了，迈克，够了就够了，现在你爱菲比，她也爱你，所以你需要忘掉你的“我永远不想结婚”这件事，站起来！</p></blockquote><p><strong>Mike:</strong> Who is this?</p><blockquote><p>你是谁？</p></blockquote><p><strong>Monica Geller:</strong> This is Monica! I&#39;m Phoebe&#39;s friend. Listen, Phoebe is back with David and he&#39;s going to propose to her, and she is going to say &quot;yes&quot; but I know she really wants to be with you!</p><blockquote><p>我是莫妮卡！我是菲比的朋友。听着，菲比和大卫回来了，他要向她求婚，她会说“是”，但我知道她真的很想和你在一起！</p></blockquote><p><strong>Mike:</strong> (sounds shocked and sits down) He... he&#39;s gonna propose?</p><blockquote><p>（听起来很震惊，坐了下来）他。。。他要求婚？</p></blockquote><p><strong>Monica Geller:</strong> I... I&#39;m sorry, did you say something? I can&#39;t hear through all this damned hair! (Tries to move her huge hair away from the phone, in vain)</p><blockquote><p>我。。。对不起，你说什么了吗？我听不清这该死的头发！（试图把她的大头发从手机上移开，但没有成功）</p></blockquote><p><strong>Mike:</strong> Look, if Phoebe wants to marry David, she should, I&#39;m not gonna stand in the way of that and neither should you.</p><blockquote><p>听着，如果菲比想嫁给大卫，她应该，我不会阻止的，你也不应该。</p></blockquote><p><strong>Monica Geller:</strong> You don&#39;t tell me what to do! I tell you what to do! Just call her. She&#39;s at the Paradise Hotel in Barbados. And while I&#39;ve got you, you&#39;ve got curly hair. What do you do in humidity? (Mike hangs up the phone) Damnit!</p><blockquote><p>你不告诉我该怎么做！我告诉你该怎么做！打电话给她就行了。她在巴巴多斯的天堂酒店。虽然我有你，你却有卷发。你在潮湿的环境中做什么？（迈克挂断电话）该死！</p></blockquote><p><em>(Chandler walks in)</em></p><blockquote><p><em>（钱德勒走进来）</em></p></blockquote><p><strong>Monica Geller:</strong> (sarcastically) Well, I hope you&#39;re happy!</p><blockquote><p>（讽刺地）好吧，我希望你快乐！</p></blockquote><p><strong>Chandler Bing:</strong> (pretending not to sense the tone) Oooh! I hope you&#39;re happy too, honey!</p><blockquote><p>（假装没有感觉到声音）哦！我希望你也快乐，亲爱的！</p></blockquote><p><strong>Monica Geller:</strong> Phoebe is going to say &quot;Yes&quot; to David. See, that&#39;s what happens when you meddle in people&#39;s lives!</p><blockquote><p>菲比会答应大卫的。看，这就是你干涉别人生活的后果！</p></blockquote><p><strong>Chandler Bing:</strong> Phoebe is going to say &quot;yes&quot;? That&#39;s, that&#39;s great!</p><blockquote><p>菲比会说“是”吗？太好了，太好了！</p></blockquote><p><strong>Monica Geller:</strong> No it&#39;s not, b&#39;cause she&#39;s still in love with Mike!</p><blockquote><p>不，不是，因为她还爱着迈克！</p></blockquote><p><strong>Chandler Bing:</strong> And there&#39;s not chance that will work?</p><blockquote><p>那就不可能了？</p></blockquote><p><strong>Monica Geller:</strong> No, I called him. It&#39;s not gonna happen.</p><blockquote><p>没有，我打电话给他了。这不会发生的。</p></blockquote><p><strong>Chandler Bing:</strong> (pointing at her) Oooooooh! Meddler! Meddler!</p><blockquote><p>（指着她）噢！多管闲事！多管闲事！</p></blockquote><p><strong>Monica Geller:</strong> Well, if you hadn&#39;t meddled to start with, I wouldn&#39;t have had to go in there and meddle myself. Now, no matter how much we meddle, we will never be able to un-meddle the thing that you meddled up - in the first place!</p><blockquote><p>好吧，如果你一开始不插手的话，我就不必进去插手了。现在，不管我们管了多少事，我们永远都无法从你管的事情中解脱出来——首先！</p></blockquote><p><strong>Chandler Bing:</strong> This vacation sucks!!</p><blockquote><p>这个假期糟透了！！</p></blockquote><hr><p>🎬 <em>The hall, full of paleontologists. Rachel and Joey are walking around</em></p><blockquote><p>🎬 <em>大厅里挤满了古生物学家。瑞秋和乔伊在四处走动</em></p></blockquote><p><strong>Joey Tribbiani:</strong> I&#39;m so bored! Stupid rain, we... we can&#39;t do anything.</p><blockquote><p>我好无聊！愚蠢的雨，我们。。。我们什么都做不了。</p></blockquote><p><strong>Rachel Green:</strong> Well, I&#39;ve brought some books. We could read.</p><blockquote><p>嗯，我带了一些书。我们可以阅读。</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey, it hasn&#39;t come to that yet.</p><blockquote><p>嘿，还没到那个地步。</p></blockquote><p><em>(A waiter walks by carrying appetizers or something on a tray)</em></p><blockquote><p><em>（服务员端着开胃菜或托盘上的东西走过）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> (stopping the waiter) Hey hey hey! Don&#39;t mind if I do!</p><blockquote><p>（拦住服务员）嘿嘿嘿！别介意我这么做！</p></blockquote><p><strong>Waiter:</strong> I&#39;m sorry sir, these are for the pharmaceutical convention (walks away)</p><blockquote><p>对不起，先生，这些是为医药会议准备的（走开）</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey Rach, do you feel like going to a convention?</p><blockquote><p>嘿，瑞秋，你想去参加一个会议吗？</p></blockquote><p><strong>Rachel Green:</strong> We can&#39;t. We&#39;re not pharmacists!</p><blockquote><p>我们不能。我们不是药剂师！</p></blockquote><p><strong>Joey Tribbiani:</strong> (walking to a table with many badges on it) I know we&#39;re not, but (he picks up a badge) Frank Medeio and... (picks up another badge) Eva Trorro... womba...</p><blockquote><p>（走向一张有很多徽章的桌子）我知道我们不是，但是（他拿起徽章）弗兰克·梅代奥和。。。（拿起另一枚徽章）伊娃·特罗罗。。。袋熊。。。</p></blockquote><p><strong>Rachel Green:</strong> (picking up another random badge) Kate Miller?</p><blockquote><p>（拿起另一枚随机徽章）凯特·米勒？</p></blockquote><p><strong>Joey Tribbiani:</strong> Kate Miller it is. (he picks up the Kate Miller badge and sticks it on Rachel&#39;s breast)</p><blockquote><p>是凯特·米勒。（他拿起凯特·米勒徽章，贴在瑞秋的胸前）</p></blockquote><p><strong>Rachel Green:</strong> And... that&#39;s the most sex I&#39;m gonna have this weekend.</p><blockquote><p>还有。。。这是我这个周末最多的性爱了。</p></blockquote><p><strong>Joey Tribbiani:</strong> In that case should I make sure it&#39;s on real good? (he does so, repeatedly tapping on her breast and stroking it)</p><blockquote><p>那样的话，我应该确保它真的很好吗？（他这样做了，反复拍打她的胸部并抚摸它）</p></blockquote><p><strong>Rachel Green:</strong> Thank you. (they walk away)</p><blockquote><p>谢谢你。（他们走开了）</p></blockquote><hr><p>🎬 <em>Ross&#39;s room. Charlie is sitting on the bed, while Ross is walking up and down nervously</em></p><blockquote><p>🎬 <em>罗斯的房间。查理坐在床上，罗斯紧张地走来走去</em></p></blockquote><p><strong>Charlie:</strong> And then, and then you said that thing about, about bringing the Mesozoic era in the 21st century.</p><blockquote><p>然后，然后你说，把中生代带到21世纪。</p></blockquote><p><strong>Ross Geller:</strong> Yeah, that&#39;s it?</p><blockquote><p>是的，就这样？</p></blockquote><p><strong>Charlie:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Ross Geller:</strong> Oh my God, we did it! (he sits beside her and skims through her notes excitedly)</p><blockquote><p>天啊，我们成功了！（他坐在她身边，兴奋地浏览着她的笔记）</p></blockquote><p><strong>Charlie:</strong> Actually I did it Ross. You remembered shockingly little of your own speech.</p><blockquote><p>实际上是我干的，罗斯。你对自己的演讲几乎记不起来。</p></blockquote><p><strong>Ross Geller:</strong> Yes, but I did make a pyramid out of the bath products. This is amazing, thank you, thank you so much. (he leans in, and they look at each other for a moment) That&#39;s a pretty necklace.</p><blockquote><p>是的，但我确实用沐浴用品做了一个金字塔。这太棒了，谢谢，非常感谢。（他弯下身，他们互相看了一会儿）那条项链真漂亮。</p></blockquote><p><strong>Charlie:</strong> Thank you.</p><blockquote><p>谢谢。</p></blockquote><p><strong>Ross Geller:</strong> Hey, what do you say we celebrate? Champagne? (he goes to get the champagne)</p><blockquote><p>嘿，我们庆祝一下怎么样？香槟（他去拿香槟）</p></blockquote><p><strong>Charlie:</strong> Oh yeah! Hey, save the cork and then we can fill the bottle with water and put it back so they don&#39;t charge you.</p><blockquote><p>哦，是的！嘿，保存好软木塞，然后我们可以把瓶子装满水，放回原处，这样他们就不会向你收费了。</p></blockquote><p><strong>Ross Geller:</strong> Oh my God, I love you.</p><blockquote><p>天啊，我爱你。</p></blockquote><p><strong>Charlie:</strong> Oh, this is such a cute picture of Emma. And is this your son... or just some kid whose picture you bring on vacation?</p><blockquote><p>哦，这张艾玛的照片真可爱。这是你儿子吗。。。或者只是一个孩子，你在度假时带了他的照片？</p></blockquote><p><strong>Ross Geller:</strong> That&#39;s Ben, my son from my first marriage.</p><blockquote><p>那是本，我第一次结婚的儿子。</p></blockquote><p><strong>Charlie:</strong> Your first marriage?</p><blockquote><p>你的第一次婚姻？</p></blockquote><p><strong>Ross Geller:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><strong>Charlie:</strong> You&#39;re married more than once?</p><blockquote><p>你结过不止一次婚？</p></blockquote><p><strong>Ross Geller:</strong> No. (they clink glasses and drink)</p><blockquote><p>不。（他们碰杯喝酒）</p></blockquote><p><strong>Charlie:</strong> So, why did you break up?</p><blockquote><p>那你为什么分手？</p></blockquote><p><strong>Ross Geller:</strong> (embarassed) Oh, it was... it&#39;s complicated, you know? She... she was... eh... gay.</p><blockquote><p>（尴尬地）哦，是。。。这很复杂，你知道吗？她。。。她是。。。嗯。。。同性恋者</p></blockquote><p><strong>Charlie:</strong> Oh my God, this is so cool!</p><blockquote><p>哦，天哪，这太酷了！</p></blockquote><p><strong>Ross Geller:</strong> Ok, odd thing to get excited about!</p><blockquote><p>好吧，奇怪的事情让人兴奋！</p></blockquote><p><strong>Charlie:</strong> No, it&#39;s just... I was enganged to a guy who turned out to be gay!</p><blockquote><p>不，只是。。。我被一个原来是同性恋的家伙迷住了！</p></blockquote><p><strong>Ross Geller:</strong> Hey! High-five! (they high-five)</p><blockquote><p>嘿！击掌！（他们击掌）</p></blockquote><p><strong>Charlie:</strong> Didn&#39;t you feel so stupid that you didn&#39;t see the signs? My fiancé was always going away on these long weekends with his tennis partner.</p><blockquote><p>难道你不觉得自己很愚蠢，没有看到这些标志吗？在这些漫长的周末，我的未婚夫总是和他的网球搭档外出。</p></blockquote><p><strong>Ross Geller:</strong> My wife had a workout friend she went to the gym with everyday for a year. She didn&#39;t get any fitter.</p><blockquote><p>我妻子有一个锻炼的朋友，她一年来每天都和她一起去健身房。她没有找到合适的人。</p></blockquote><p><strong>Charlie:</strong> Right and then everybody finds out and they&#39;re like: &quot;Oh, I knew all along&quot;</p><blockquote><p>对，然后每个人都发现了，他们说：“哦，我早就知道了”</p></blockquote><p><strong>Ross Geller:</strong> I know! It&#39;s like, if you knew, why didn&#39;t you tell me, you know? I mean, call, or leave a note: &quot;Hi, I just dropped by to say your wife&#39;s gay&quot;</p><blockquote><p>我知道！就像，如果你知道，你为什么不告诉我，你知道吗？我的意思是，打个电话，或者留个便条：“嗨，我只是顺道来说你妻子是同性恋”</p></blockquote><p><strong>Charlie:</strong> I know!</p><blockquote><p>我知道！</p></blockquote><p><strong>Ross Geller:</strong> And then, you try to make the best of a bad situation, so you float the idea of a threesome?</p><blockquote><p>然后，你试图在糟糕的情况下发挥最大的作用，所以你就有了三人行的想法？</p></blockquote><p><strong>Charlie:</strong> I didn&#39;t do that.</p><blockquote><p>我没那么做。</p></blockquote><p><strong>Ross Geller:</strong> (embarassed) Me neither.</p><blockquote><p>（尴尬地）我也是。</p></blockquote><hr><p>🎬 <em>the Pharmacist convention. Joey and Rachel are walking out of it, drinking cocktails</em></p><blockquote><p>🎬 <em>药剂师大会。乔伊和瑞秋正走出会场，喝着鸡尾酒</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Well, who knew? Pharmacists are fun.</p><blockquote><p>谁知道呢？药剂师很有趣。</p></blockquote><p><strong>Rachel Green:</strong> I know, that old lady at the end was ready to take you home.</p><blockquote><p>我知道，最后那个老太太准备带你回家。</p></blockquote><p><strong>Joey Tribbiani:</strong> Not enough pills in the world, Rach. What about you, you&#39;re the single one, seen anybody in there you like?</p><blockquote><p>世界上没有足够的药片，瑞秋。那你呢，你是单身汉，有没有看到你喜欢的人？</p></blockquote><p><strong>Rachel Green:</strong> Well, let&#39;s see. There was a really big guy that I was talking to, with the really nice breasts...</p><blockquote><p>好吧，让我想想。我在和一个大块头说话，他胸部很好。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> But what about back home, anything going on there? Anybody you like?</p><blockquote><p>但是在家里呢，有什么事吗？你喜欢谁？</p></blockquote><p><strong>Rachel Green:</strong> (takes a sip from her drink, embarassed) No.</p><blockquote><p>（尴尬地喝了一小口）不。</p></blockquote><p><strong>Joey Tribbiani:</strong> There it is, you&#39;re blushing!</p><blockquote><p>在这儿，你脸红了！</p></blockquote><p><strong>Rachel Green:</strong> No, I&#39;m not blushing, I&#39;m sunburnt! From, you know, the rain.</p><blockquote><p>不，我没有脸红，我晒黑了！因为，你知道，下雨。</p></blockquote><p><strong>Joey Tribbiani:</strong> You like someone. Tell me who it is. Who is it? (tickles her a little)</p><blockquote><p>你喜欢某人。告诉我是谁。是谁？（让她觉得有点痒）</p></blockquote><p><strong>Rachel Green:</strong> No.</p><blockquote><p>没有。</p></blockquote><p><strong>Joey Tribbiani:</strong> Tell me who it is.</p><blockquote><p>告诉我是谁。</p></blockquote><p><strong>Rachel Green:</strong> Joey! (she walks away; Joey goes after her teasing and tickling her)</p><blockquote><p>乔伊！（她走开了；乔伊追着她逗她，挠她痒痒）</p></blockquote><p><strong>Joey Tribbiani:</strong> Come on who? Who do you like? Tell me. You&#39;re not getting away that easy. Who do you like, who?</p><blockquote><p>来吧，谁？你喜欢谁？告诉我。你逃不了那么容易。你喜欢谁，谁？</p></blockquote><p><strong>Rachel Green:</strong> Joey, come on! It doesn&#39;t matter, you know, it&#39;s not like anything&#39;s gonna happen.</p><blockquote><p>乔伊，快点！不要紧，你知道，不会有什么事发生的。</p></blockquote><p><strong>Joey Tribbiani:</strong> What? Why not? Rach, who can you not get?</p><blockquote><p>什么？为什么不呢？瑞秋，你找不到谁？</p></blockquote><p><strong>Rachel Green:</strong> Oh! (pause) Ok. Ok, you really wanna know who it is?</p><blockquote><p>哦！（停顿）好的。好吧，你真的想知道是谁吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> (eagerly) Yeah, who is that?</p><blockquote><p>（急切地）是的，那是谁？</p></blockquote><p><strong>Rachel Green:</strong> Do ya?</p><blockquote><p>是吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah.</p><blockquote><p>是的。</p></blockquote><p><em>(Ross and Charlie walk into the hall from Ross&#39;s room)</em></p><blockquote><p><em>（罗斯和查理从罗斯的房间走进大厅）</em></p></blockquote><p><strong>Ross and Charlie:</strong> Hey!</p><blockquote><p>嘿！</p></blockquote><p><em>(Joey smiles at them. Rachel looks annoyed)</em></p><blockquote><p><em>（乔伊对他们微笑。瑞秋看起来很生气）</em></p></blockquote><p><strong>Charlie:</strong> (to Joey) I just left you a message! Ross and I were gonna go grab a bite, but now that you&#39;re here, maybe we can go have that dinner.</p><blockquote><p>（对乔伊）我刚给你留了个口信！罗斯和我本来想去吃点东西，但现在你来了，也许我们可以去吃晚饭。</p></blockquote><p><strong>Joey Tribbiani:</strong> Right, of course. Hey, did you guys finish the speech?</p><blockquote><p>对，当然。嘿，你们讲完了吗？</p></blockquote><p><strong>Ross Geller:</strong> Yep, we got it, we got it. (To Charlie) Thank you so much.</p><blockquote><p>是的，我们知道了，我们知道了。（对查理）非常感谢你。</p></blockquote><p><strong>Charlie:</strong> I had a great time.</p><blockquote><p>我玩得很开心。</p></blockquote><p><strong>Joey Tribbiani:</strong> Alright, hey look, and this isn&#39;t over, because I really wanna know who...</p><blockquote><p>好吧，嘿，看，这还没结束，因为我真的想知道谁。。。</p></blockquote><p><strong>Rachel Green:</strong> Later! La...</p><blockquote><p>待会儿！洛杉矶。。。</p></blockquote><p><strong>Charlie:</strong> So, shall we?</p><blockquote><p>那么，我们可以吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah. (they leave)</p><blockquote><p>是的。（他们离开了）</p></blockquote><p><strong>Rachel Green:</strong> Ok. See you, bye.</p><blockquote><p>好的。再见，再见。</p></blockquote><p><strong>Charlie:</strong> Bye.</p><blockquote><p>再见。</p></blockquote><p><strong>Ross Geller:</strong> Good night.</p><blockquote><p>晚安。</p></blockquote><p><strong>Joey Tribbiani:</strong> Night.</p><blockquote><p>晚上好。</p></blockquote><p><em>(Ross and Rachel watch them walk away and sigh. They look at each other, embarassed.)</em></p><blockquote><p><em>（罗斯和瑞秋看着他们走开，叹了口气。他们尴尬地看着对方。）</em></p></blockquote><p>Ross and **Rachel Green: **Ok, good night!</p><blockquote><p>罗斯和<strong>瑞秋·格林：</strong>好的，晚安！</p></blockquote><hr><p>🎬 <em>The restaurant. Chandler and Monica are sitting at a table</em></p><blockquote><p>🎬 <em>餐厅。钱德勒和莫妮卡坐在一张桌子旁</em></p></blockquote><p><em>(Phoebe and David walk in)</em></p><blockquote><p><em>（菲比和大卫走进来）</em></p></blockquote><p><strong>Monica Geller:</strong> I can&#39;t believe she&#39;s gonna say yes to David. She&#39;s clearly in love with Mike.</p><blockquote><p>我不敢相信她会答应大卫。她显然爱上了迈克。</p></blockquote><p><strong>Chandler Bing:</strong> You know, it&#39;s very hard to take you seriously when you look like that.</p><blockquote><p>你知道，当你长得那样的时候，很难把你当回事。</p></blockquote><p><em>(David and Phoebe sit down at a table close to Chandler and Monica&#39;s)</em></p><blockquote><p><em>（大卫和菲比坐在钱德勒和莫妮卡旁边的桌子旁）</em></p></blockquote><p><strong>David:</strong> Uh, Phoebe, uh, I have... something I wanna say.</p><blockquote><p>嗯，菲比，嗯，我有。。。我想说点什么。</p></blockquote><p><strong>Monica Geller:</strong> Oh my God, he&#39;s gonna do it now. Please, I cannot watch this, let&#39;s go.</p><blockquote><p>哦，我的天，他现在就要做了。拜托，我不能看这个，走吧。</p></blockquote><p><strong>Chandler Bing:</strong> I think we have some time. Have you ever heard him talk? (doing David) &quot;Uh, Phoebe, uh, I would be honoured, uh...&quot; Spit it out, David!</p><blockquote><p>我想我们还有时间。你听过他说话吗？（模仿大卫）“呃，菲比，呃，我很荣幸，呃……”说出来，大卫！</p></blockquote><p><strong>David:</strong> Uh, Phoebe, uh... (Chandler hits his own head) you&#39;re an amazing woman, and the time we spent apart was, was unbearable. Of course the sanitation strikes in Minsk didn&#39;t help!</p><blockquote><p>嗯，菲比，嗯。。。（钱德勒敲了敲自己的头）你是一个了不起的女人，我们分开的时间是，令人难以忍受的。明斯克的卫生罢工当然没有帮助！</p></blockquote><p><strong>Phoebe Buffay:</strong> Sure, ok, yeah.</p><blockquote><p>当然，好的，是的。</p></blockquote><p><strong>David:</strong> But well, now that we&#39;re together again, I don&#39;t ever want to be apart. So, to that end...</p><blockquote><p>但现在我们又在一起了，我再也不想分开了。所以，为了这个目的。。。</p></blockquote><p><em>(David produces the ring. At the same time, Mike walks in, behind David)</em></p><blockquote><p><em>（大卫拿出戒指。与此同时，迈克走了进来，在大卫后面）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Oh my God, Mike!</p><blockquote><p>哦，天哪，迈克！</p></blockquote><p><strong>David:</strong> It&#39;s David, actually!</p><blockquote><p>实际上是大卫！</p></blockquote><p><strong>Phoebe Buffay:</strong> No, Mike&#39;s here.</p><blockquote><p>不，迈克在这儿。</p></blockquote><p><strong>David:</strong> (turns around) Hi Mike!</p><blockquote><p>（转过身）嗨，迈克！</p></blockquote><p><strong>Mike:</strong> Hi David. Chandler. Monica... (Looks at Monica, checking her big hair, aghast) Oh!</p><blockquote><p>嗨，大卫。经销商莫妮卡。。。（看着莫妮卡，检查她的大头发，惊呆了）哦！</p></blockquote><p><strong>Monica Geller:</strong> IT&#39;S THE HUMIDITY!</p><blockquote><p>是湿气！</p></blockquote><p><strong>Mike:</strong> Hi Phoebe.</p><blockquote><p>嗨，菲比。</p></blockquote><p><strong>Phoebe Buffay:</strong> What are you, what are you doing here?</p><blockquote><p>你在这里干什么？</p></blockquote><p><strong>Mike:</strong> I have a question I need to ask you.</p><blockquote><p>我有个问题要问你。</p></blockquote><p><strong>David:</strong> I have a question I was kinda gonna ask her myself.</p><blockquote><p>我有个问题，我想自己问她。</p></blockquote><p><strong>Mike:</strong> Yeah, I understand, but before you do, she really needs to hear this.</p><blockquote><p>是的，我明白，但在你这么做之前，她真的需要听听这个。</p></blockquote><p><strong>David:</strong> (annoyed) Ok, would you care for my seat as well?</p><blockquote><p>（恼怒地）好的，你也要我的座位吗？</p></blockquote><p><strong>Mike:</strong> Actually yeah, that&#39;ll be great.</p><blockquote><p>事实上是的，那太好了。</p></blockquote><p><strong>David:</strong> That&#39;s fair, you&#39;ve had a long trip. (he leaves his seat to Mike, and stands there looking for a chair. He finally goes to Monica and Chandler&#39;s table)</p><blockquote><p>这很公平，你已经走了很长一段路了。（他把座位让给迈克，站在那里找椅子。最后他走向莫妮卡和钱德勒的桌子）</p></blockquote><p><strong>Mike:</strong> Phoebe, I love you. I mean, I missed you so much these last few months and I thought we were apart for a good reason, but then I suddenly realized that there was no reason good enough to keep me from spending the rest of my life with you.</p><blockquote><p>菲比，我爱你。我的意思是，在过去的几个月里，我非常想念你，我认为我们分开有一个很好的理由，但后来我突然意识到没有足够好的理由阻止我与你共度余生。</p></blockquote><p><strong>David:</strong> Kinda stepped on the toes of what I was going to say.</p><blockquote><p>有点踩到了我要说的话的脚趾。</p></blockquote><p><strong>Mike:</strong> Sorry David, but she really has to know this.</p><blockquote><p>对不起，大卫，但她真的必须知道这一点。</p></blockquote><p><strong>David:</strong> Alright, but after this I want to see you outside. If the rain stops.</p><blockquote><p>好吧，但这之后我想在外面见你。如果雨停了。</p></blockquote><p><strong>Monica Geller:</strong> You&#39;re the most incredible woman I&#39;ve ever met. How can I lose you? (Phoebe looks very flattered) Now, I don&#39;t actually have a ring...</p><blockquote><p>你是我见过的最不可思议的女人。我怎么会失去你？（菲比看起来很受宠若惊）现在，我实际上没有戒指。。。</p></blockquote><p><strong>David:</strong> I have a ring.</p><blockquote><p>我有一枚戒指。</p></blockquote><p><strong>Chandler Bing:</strong> I wouldn&#39;t brag too much about that thing, big guy.</p><blockquote><p>我不会为那件事吹嘘太多，大个子。</p></blockquote><p><strong>David:</strong> Phoebe, will you marry me?</p><blockquote><p>菲比，你愿意嫁给我吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (smiles at him happily for a few seconds before answering) No!</p><blockquote><p>（高兴地笑了几秒钟才回答）不！</p></blockquote><p><strong>David:</strong> Uhm... Ha ha!</p><blockquote><p>嗯。。。哈哈！</p></blockquote><p><strong>Phoebe Buffay:</strong> I love you. But I never needed a proposal from you. I just needed to know that we were headed somewhere, you know, that we had a future.</p><blockquote><p>我爱你。但我从不需要你的建议。我只是想知道我们正朝着某个方向前进，你知道，我们有未来。</p></blockquote><p><strong>Mike:</strong> We can have any future you want.</p><blockquote><p>我们可以有你想要的任何未来。</p></blockquote><p><em>(they hold their hands, gazing at each other)</em></p><blockquote><p><em>（他们握着手，互相凝视着）</em></p></blockquote><p><strong>David:</strong> Ok, I&#39;m gonna take off.</p><blockquote><p>好的，我要走了。</p></blockquote><p><strong>Phoebe Buffay:</strong> David, I&#39;m so sorry, I&#39;m sorry.</p><blockquote><p>大卫，我很抱歉，我很抱歉。</p></blockquote><p><strong>David:</strong> Just so I know, if I had asked first...</p><blockquote><p>我知道，如果我先问的话。。。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, I might have said yes, but that would have been wrong.</p><blockquote><p>是的，我可能会说是的，但那是错的。</p></blockquote><p><strong>David:</strong> Please, you don&#39;t have to explain. I mean, perhaps if I hadn&#39;t gone to Minsk things would have worked out for us. And I wouldn&#39;t have ruined my career, or lost that toe to frostbite. It was a good trip! (he leaves)</p><blockquote><p>拜托，你不必解释。我的意思是，如果我没有去明斯克，事情可能会对我们有好处。我不会毁了我的事业，也不会因为冻伤而失去脚趾。这是一次愉快的旅行！（他离开了）</p></blockquote><p><strong>Mike:</strong> Is it ok if I hug you now?</p><blockquote><p>我现在拥抱你可以吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> Yes! (they hug)</p><blockquote><p>是的！（他们拥抱）</p></blockquote><p><strong>Monica Geller:</strong> (to everybody) BECAUSE OF OUR MEDDLING! Alright?</p><blockquote><p>（对大家）因为我们的干涉！好吧</p></blockquote><hr><p>🎬 <em>Monica and Chandler&#39;s room. Monica and Chandler are in bed.</em></p><blockquote><p>🎬 <em>莫妮卡和钱德勒的房间。莫妮卡和钱德勒在床上。</em></p></blockquote><p><strong>Chandler Bing:</strong> Oh, ain&#39;t this nice? It&#39;s so quiet, I could just lie here all day.</p><blockquote><p>哦，这不是很好吗？太安静了，我可以整天躺在这里。</p></blockquote><p><strong>Monica Geller:</strong> I know (she snuggles to him)</p><blockquote><p>我知道（她依偎着他）</p></blockquote><p><em>(Rachel runs in)</em></p><blockquote><p><em>（瑞秋跑了进来）</em></p></blockquote><p><strong>Rachel Green:</strong> (walking in hurriedly) Open your drapes! Open your drapes!</p><blockquote><p>（匆匆走进来）打开窗帘！打开窗帘！</p></blockquote><p><strong>Chandler Bing:</strong> I&#39;m so glad we&#39;ve got adjoining rooms!</p><blockquote><p>我很高兴我们有相邻的房间！</p></blockquote><p><em>(Rachel opens the drapes)</em></p><blockquote><p><em>（瑞秋打开窗帘）</em></p></blockquote><p><strong>Monica Geller:</strong> The sun is out!</p><blockquote><p>太阳出来了！</p></blockquote><p><strong>Chandler Bing:</strong> Hey! Remember when I had corneas?</p><blockquote><p>嘿！还记得我有角膜的时候吗？</p></blockquote><p><strong>Monica Geller:</strong> Ok listen, you go down to the pool and reserve the chairs, and I&#39;ll get the magazines and the lotion.</p><blockquote><p>好的，听着，你去游泳池预订椅子，我去拿杂志和乳液。</p></blockquote><p><strong>Chandler Bing:</strong> Ladies? Ross&#39;s speech is in 45 minutes.</p><blockquote><p>女士们？罗斯的演讲还有45分钟。</p></blockquote><p><strong>Rachel Green:</strong> Nooo!</p><blockquote><p>不！</p></blockquote><p><strong>Monica Geller:</strong> Damn it!</p><blockquote><p>该死！</p></blockquote><p><strong>Ross Geller:</strong> (from across the wall) Walls are pretty thin, guys!</p><blockquote><p>（隔墙）墙很薄，伙计们！</p></blockquote><hr><p>🎬 <em>Conference room. Ross is making his keynote speech</em></p><blockquote><p>🎬 <em>会议室。罗斯正在做主题演讲</em></p></blockquote><p><strong>Ross Geller:</strong> Then we have to await the data from recent MRI scans and DNA testing which call into question information gathered from years of simple carbon dating.</p><blockquote><p>然后我们必须等待最近核磁共振扫描和DNA测试的数据，这些数据对多年来简单碳年代测定所收集到的信息提出了质疑。</p></blockquote><p><strong>Rachel Green:</strong> Look at that woman sitting by the pool getting tan... so leathery and wrinkled, I&#39;m so jealous!</p><blockquote><p>看那个坐在游泳池边晒成棕褐色的女人。。。皮包骨头，满脸皱纹，我好嫉妒！</p></blockquote><p><strong>Ross Geller:</strong> Finally, factoring the profusion of new species recently discovered: Gigantosaurus, Argentinasaurus...</p><blockquote><p>最后，考虑到最近发现的大量新物种：巨龙、阿根廷龙。。。</p></blockquote><p><strong>Chandler Bing:</strong> (to a paleontologist sitting next to him) Not to mention the cold sores.</p><blockquote><p>（对坐在他旁边的古生物学家说）更不用说那些冻疮了。</p></blockquote><p><em>(the paleontologist glares at Chandler)</em></p><blockquote><p><em>（古生物学家瞪着钱德勒）</em></p></blockquote><p><strong>Ross Geller:</strong> And that&#39;s just the herbivores. I&#39;m not even gonna discuss the carnivores, their heads are already too big. Which is ironic considering their stunted cerebral development.</p><blockquote><p>那只是食草动物。我甚至不想讨论食肉动物，它们的头已经太大了。考虑到他们发育不良的大脑，这是具有讽刺意味的。</p></blockquote><p><em>(all the paleontologists laugh)</em></p><blockquote><p><em>（所有古生物学家都笑了）</em></p></blockquote><p><strong>Chandler Bing:</strong> (to the one sitting next to him) Really?</p><blockquote><p>（对坐在他旁边的人）真的吗？</p></blockquote><p><strong>Ross Geller:</strong> But all kidding aside, in much the same way that Homo ergaster [1] is now thought to be a separate species from Homo erectus...</p><blockquote><p>但除了开玩笑，就像现在认为麦加斯特人是直立人的一个独立物种一样。。。</p></blockquote><p><em>(Joey laughs)</em></p><blockquote><p><em>（乔伊笑了）</em></p></blockquote><p><strong>Charlie:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> He said &quot;erectus&quot;!</p><blockquote><p>他说“直立人”！</p></blockquote><p><strong>Charlie:</strong> You&#39;re... you&#39;re kidding, right?</p><blockquote><p>你。。。你在开玩笑吧？</p></blockquote><p><strong>Joey Tribbiani:</strong> No, he really said it.</p><blockquote><p>不，他真的说了。</p></blockquote><p><strong>Ross Geller:</strong> ... and while there are certainly vast differences between these Mesozoic fossiles and the example of Homo erectus...</p><blockquote><p>。。。虽然这些中生代化石和直立人的例子之间确实存在巨大差异。。。</p></blockquote><p><em>(Rachel laughs)</em></p><blockquote><p><em>（瑞秋笑了）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Erectus?</p><blockquote><p>直立人？</p></blockquote><p><strong>Rachel Green:</strong> Homo.</p><blockquote><p>同性恋。</p></blockquote><hr><p>🎬 <em>the hotel conference room</em></p><blockquote><p>🎬 <em>酒店会议室</em></p></blockquote><p><strong>Ross Geller:</strong> (concluding his speech)... in a very real way we can bring the Mesozoic era into the 21st century. (pauses) Thank you!</p><blockquote><p>（结束他的演讲）。。。以一种非常真实的方式，我们可以将中生代带入21世纪。（停顿）谢谢！</p></blockquote><p><em>(Everybody stands up and applauds. Ross looks flattered and surprised. His friends and other members of the audience go to congratulate him)</em></p><blockquote><p><em>（每个人都站起来鼓掌。罗斯看起来既受宠若惊又惊讶。他的朋友和其他观众去祝贺他）</em></p></blockquote><p><strong>Ross Geller:</strong> Oh, thanks guys!</p><blockquote><p>哦，谢谢你们！</p></blockquote><p><strong>Man with a bow tie:</strong> (shaking hands with Ross) I thought... it was wonderful!</p><blockquote><p>（和罗斯握手）我想。。。太棒了！</p></blockquote><p><strong>Ross Geller:</strong> Oh!</p><blockquote><p>哦！</p></blockquote><p><strong>Man with a bow tie:</strong> Jarvis Oberblau, Cornell. (sighs) I mean, the ideas you put forth and, and from someone... so... young... and... (sighs again and smiles at Ross blissfully).</p><blockquote><p>贾维斯·奥伯劳，康奈尔州。（叹气）我的意思是，你提出的想法，以及来自某人的想法。。。所以年轻的。。。而且。。。（再次叹气，幸福地对罗斯微笑）。</p></blockquote><p><strong>Ross Geller:</strong> (with a frozen smile on his face, realizing something&#39;s wrong with Jarvis) Ok... now... now we&#39;re just holding hands! (pulls his hand away)</p><blockquote><p>（脸上带着冷冰冰的微笑，意识到贾维斯有些不对劲）好吧。。。现在。。。现在我们只是手牵手！（把他的手拉开）</p></blockquote><p><strong>Rachel Green:</strong> All right! Well, uh... (to Monica) we&#39;re gonna hit the beach?</p><blockquote><p>好吧！嗯，嗯。。。（对莫妮卡）我们要去海滩？</p></blockquote><p><strong>Monica Geller:</strong> Yeah!</p><blockquote><p>是啊！</p></blockquote><p><strong>Rachel Green:</strong> (to Ross, in a flattering tone) It was really... great!</p><blockquote><p>（以奉承的口吻对罗斯）真的。。。伟大的</p></blockquote><p><strong>Ross Geller:</strong> Oh, thank you so much!</p><blockquote><p>哦，非常感谢你！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, and so funny!</p><blockquote><p>是啊，太有趣了！</p></blockquote><p><strong>Rachel Green:</strong> Oh!</p><blockquote><p>哦！</p></blockquote><p><em>(Rachel, Joey and Chandler pat him on his shoulders and walk off, together with Monica)</em></p><blockquote><p><em>（瑞秋、乔伊和钱德勒拍拍他的肩膀，然后和莫妮卡一起走了）</em></p></blockquote><p><strong>Ross Geller:</strong> (puzzled) Ok!... All right, thanks! Thank you so much, you guys! (to Phoebe) Oh, I can&#39;t tell you how much it means to me that you were here!</p><blockquote><p>（困惑地）好吧！。。。好的，谢谢！非常感谢你们，伙计们！（对菲比）哦，我不能告诉你你在这里对我有多重要！</p></blockquote><p><strong>Mike:</strong> (popping by, smiling) You&#39;re kidding, we wouldn&#39;t have missed it!</p><blockquote><p>（突然走过，微笑着）你在开玩笑，我们不会错过的！</p></blockquote><p><em>(Ross is dumbfounded to see Mike instead of David)</em></p><blockquote><p><em>（罗斯目瞪口呆地看到迈克而不是大卫）</em></p></blockquote><p><strong>Mike:</strong> Oh... I&#39;m back!</p><blockquote><p>哦。。。我回来了！</p></blockquote><p><strong>Ross Geller:</strong> (skating over, embarrassed) Ok!... Uh... excuse me? Yeah?</p><blockquote><p>（滑冰，不好意思）好的！。。。UH打扰一下是 啊</p></blockquote><p>Phoebe &amp; Mike: Yeah! (they leave)</p><blockquote><p>是啊！（他们离开了）</p></blockquote><p><em>(Ross goes towards Charlie, who&#39;s conversing with a fellow paleontologist, and touches her shoulder to get her attention)</em></p><blockquote><p><em>（罗斯走向查理，查理正在和一位古生物学家同伴交谈，并摸了摸她的肩膀以引起她的注意）</em></p></blockquote><p><strong>Ross Geller:</strong> Hey! (she turns to him) Well...? (in expectation)</p><blockquote><p>嘿！（她转向他）嗯。。。？（期待中）</p></blockquote><p><strong>Charlie:</strong> You were incredible!</p><blockquote><p>你太棒了！</p></blockquote><p><strong>Ross Geller:</strong> Yeah?</p><blockquote><p>是吗？</p></blockquote><p><strong>Charlie:</strong> You blew them away!</p><blockquote><p>你把他们吹走了！</p></blockquote><p><strong>Ross Geller:</strong> Oh, I can&#39;t tell you how great it was to look at the crowd and see your face! I mean... uh, did you know you were (giggles) mouthing the words along with me?</p><blockquote><p>哦，我不能告诉你看着人群看到你的脸有多棒！我是说。。。呃，你知道你（咯咯地笑）和我一起说这些话吗？</p></blockquote><p><strong>Charlie:</strong> (smiling broadly) I was not!</p><blockquote><p>（咧嘴笑）我不是！</p></blockquote><p><strong>Ross Geller:</strong> No, it&#39;s ok! Made me feel like a rock star!</p><blockquote><p>不，没关系！让我觉得自己像个摇滚明星！</p></blockquote><p><strong>Charlie:</strong> Oh my God! (pauses) I&#39;m your groupie!</p><blockquote><p>天哪！（停顿）我是你的粉丝！</p></blockquote><p><strong>Ross Geller:</strong> (joking) I&#39;d better not found you naked in my hotel room!</p><blockquote><p>（开玩笑）我最好不要在我的酒店房间里发现你裸体！</p></blockquote><p><em>(Ross giggles, but Charlie isn&#39;t amused at all.)</em></p><blockquote><p><em>（罗斯笑了，但查理一点也不觉得好笑。）</em></p></blockquote><p><strong>Ross Geller:</strong> (realizing his joke wasn&#39;t so good, but still giggling) Look, I took it too far!</p><blockquote><p>（意识到他的笑话不是很好，但还是咯咯笑）看，我开得太过分了！</p></blockquote><hr><p>🎬 <em>the hotel lobby. Monica, Phoebe, Chandler and Mike walk in from the outside.</em></p><blockquote><p>🎬 <em>酒店大厅。莫妮卡、菲比、钱德勒和迈克从外面走进来。</em></p></blockquote><p><strong>Monica Geller:</strong> (her hair bigger then before) I can&#39;t believe it&#39;s raining again! Oh, it&#39;s so unfair!!!</p><blockquote><p>（她的头发比以前大）真不敢相信又下雨了！哦，这太不公平了！！！</p></blockquote><p><em>(They approach the buffet, where a couple of paleontologists are sipping their drinks)</em></p><blockquote><p><em>（他们走近自助餐厅，几位古生物学家正在那里啜饮饮料）</em></p></blockquote><p><strong>Phoebe Buffay:</strong> Well, on the bright side, now you won&#39;t have to see all these paleontologists with their shirts off. (Grabs a drink and notices that the two men are upset) Not you guys. You got it going on!</p><blockquote><p>好吧，好的一面是，现在你不必看到所有这些脱掉衬衫的古生物学家了。（抓起一杯饮料，注意到这两个人很不高兴）不是你们。你成功了！</p></blockquote><p><em>(Monica, Phoebe, Chandler and Mike walk away, sipping their drinks)</em></p><blockquote><p><em>（莫妮卡、菲比、钱德勒和迈克喝着饮料走开了）</em></p></blockquote><p><strong>Monica Geller:</strong> So, what are we gonna do today?</p><blockquote><p>那么，我们今天要做什么？</p></blockquote><p><strong>Mike:</strong> They have a game room downstairs! Ping pong and stuff.</p><blockquote><p>楼下有游戏室！乒乓球之类的。</p></blockquote><p><strong>Monica Geller:</strong> (pleasantly surprised) Ping pong? (to Chandler) Honey, they have ping pong! Let&#39;s play!</p><blockquote><p>（惊喜地）乒乓球？（对钱德勒）亲爱的，他们有乒乓球！我们来玩吧！</p></blockquote><p><strong>Chandler Bing:</strong> I don&#39;t think so!</p><blockquote><p>我不这么认为！</p></blockquote><p><strong>Monica Geller:</strong> (disappointed) Why not?</p><blockquote><p>（失望）为什么不呢？</p></blockquote><p><strong>Chandler Bing:</strong> Because you know how competitive you get and well, I say it&#39;s cute, others disagree, and I&#39;m lying!</p><blockquote><p>因为你知道你有多么有竞争力，我说它很可爱，其他人不同意，而我在撒谎！</p></blockquote><p><strong>Monica Geller:</strong> I&#39;m not always that bad!</p><blockquote><p>我并不总是那么坏！</p></blockquote><p><strong>Chandler Bing:</strong> Oh, yeah? What happened when we played last time?</p><blockquote><p>哦，是吗？上次我们玩的时候发生了什么？</p></blockquote><p><strong>Monica Geller:</strong> (hesitatingly) I punched you...?</p><blockquote><p>（犹豫地）我打了你。。。？</p></blockquote><p><strong>Chandler Bing:</strong> And...?</p><blockquote><p>还有。。。？</p></blockquote><p><strong>Monica Geller:</strong> ... Phoebe...?</p><blockquote><p>。。。菲比。。。？</p></blockquote><p><strong>Phoebe Buffay:</strong> ... and...?</p><blockquote><p>。。。还有。。。？</p></blockquote><p><strong>Monica Geller:</strong> I clunked your heads together!</p><blockquote><p>我把你们的头撞在一起了！</p></blockquote><p><em>(Chandler turns to Mike and gives him a &quot;See what I mean?&quot; look)</em></p><blockquote><p>（钱德勒转向迈克，看了他一眼，“明白我的意思吗？”</p></blockquote><hr><p>🎬 <em>Joey and Charlie&#39;s room</em></p><blockquote><p>🎬 <em>乔伊和查理的房间</em></p></blockquote><p><em>(Joey is sitting in an armchair and wearing a diving mask. He pulls out a grape from a bunch of fake grapes on the coffee table, puts it on the snorkel&#39;s breathing tube and blows it out, then giggles to himself)</em></p><blockquote><p><em>（乔伊坐在扶手椅上，戴着潜水面具。他从咖啡桌上的一束假葡萄中拿出一颗葡萄，放在通气管上，吹灭，然后咯咯地笑）</em></p></blockquote><p><strong>Charlie:</strong> (walking in) Hey! There you are!</p><blockquote><p>（走进来）嘿！给你！</p></blockquote><p><strong>Joey Tribbiani:</strong> Hey! (stands up) As soon as it stops raining we have got to go snorkeling! Some kid told me about the sea turtle and, if you blow bubbles in its face, it chases ya! (smiles ecstatic)</p><blockquote><p>嘿！（站起来）雨一停，我们就得去浮潜！有个孩子告诉我海龟的事，如果你朝它脸上吹泡泡，它就会追你！（欣喜若狂的微笑）</p></blockquote><p><strong>Charlie:</strong> I&#39;m sorry, I can&#39;t! I&#39;m running a discussion group all afternoon.</p><blockquote><p>对不起，我不能！整个下午我都在组织一个讨论小组。</p></blockquote><p><strong>Joey Tribbiani:</strong> (disappointed) Oh... oh, but that&#39;s ok, I&#39;ll find someone else to do it... I&#39;ll do it alone, but... I don&#39;t know what happens if the sea turtle catches you...</p><blockquote><p>（失望）哦。。。哦，没关系，我会找其他人来做的。。。我会一个人做的，但是。。。我不知道如果海龟抓住你会发生什么。。。</p></blockquote><p><strong>Charlie:</strong> You know... I feel so bad! I haven&#39;t seen you this whole trip and (pauses) especially last night...</p><blockquote><p>你知道。。。我感觉很糟糕！我整个旅程都没见过你，尤其是昨晚。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> (interrupting her) Hey! Don&#39;t worry about it! It was fine! I ended up having the best time with Rachel! I just felt bad for you, stuck in that room, working on Ross&#39;s speech... (pulls a face)</p><blockquote><p>（打断她）嘿！别担心！很好！我和瑞秋玩得很开心！我只是为你感到难过，困在那个房间里，为罗斯的演讲工作。。。（拉着脸）</p></blockquote><p><strong>Charlie:</strong> Actually, it turned out to be a lot of fun!</p><blockquote><p>事实上，结果很有趣！</p></blockquote><p><strong>Joey Tribbiani:</strong> (bewildered) Oh! Oh, well! At least we&#39;re both having fun!</p><blockquote><p>（困惑）哦！哦，好吧！至少我们都玩得很开心！</p></blockquote><p><strong>Charlie:</strong> Yeah...</p><blockquote><p>是的。。。</p></blockquote><p><em>(There&#39;s an awkward moment of silence)</em></p><blockquote><p><em>（有一个尴尬的沉默时刻）</em></p></blockquote><p><strong>Charlie:</strong> ... is it weird that it&#39;s not with each other?</p><blockquote><p>。。。彼此不在一起是不是很奇怪？</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah! A little bit, yeah...</p><blockquote><p>是啊！有一点，是的。。。</p></blockquote><p><strong>Charlie:</strong> (sitting down on the bed) I think we need to talk...!</p><blockquote><p>（坐在床上）我想我们需要谈谈。。。！</p></blockquote><p><em>(pause)</em></p><blockquote><p><em>（停顿）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah... I think we do... (sighs, with folded arms)... about what?</p><blockquote><p>是的。。。我想我们是。。。（叹气，双臂交叉）。。。关于什么？</p></blockquote><hr><p>🎬 <em>the hotel game room. There is a ping pong table in the middle of the room. Monica, Phoebe, Chandler and Mike walk in</em></p><blockquote><p>酒店游戏室。房间中间有一张乒乓球桌。莫尼卡、菲比、钱德勒和迈克走进房间。</p></blockquote><p><strong>Monica Geller:</strong> C&#39;mon guys, it&#39;ll be fun!</p><blockquote><p>来吧，伙计们，会很有趣的！</p></blockquote><p><strong>Phoebe Buffay:</strong> All right, all right... I&#39;ll play if we don&#39;t keep score!</p><blockquote><p>好吧，好吧。。。如果我们不记分，我就玩！</p></blockquote><p><strong>Monica Geller:</strong> But then how do we know who wins?</p><blockquote><p>那我们怎么知道谁赢了呢？</p></blockquote><p><strong>Phoebe Buffay:</strong> Nobody wins!</p><blockquote><p>没人赢！</p></blockquote><p><strong>Monica Geller:</strong> So, we&#39;re just four losers... SUPER!</p><blockquote><p>所以，我们只是四个失败者。。。超级的！</p></blockquote><p><strong>Chandler Bing:</strong> I&#39;m not playing with you.</p><blockquote><p>我不是在和你玩。</p></blockquote><p><strong>Phoebe Buffay:</strong> Yeah, I&#39;m out.</p><blockquote><p>是的，我出去了。</p></blockquote><p><strong>Mike:</strong> I&#39;ll play ya!</p><blockquote><p>我和你玩！</p></blockquote><p><strong>Monica Geller:</strong> (smiling) OK!</p><blockquote><p>（微笑）好的！</p></blockquote><p><strong>Phoebe Buffay:</strong> Mike, you don&#39;t know, you don&#39;t know what you&#39;re doing!</p><blockquote><p>迈克，你不知道，你不知道你在做什么！</p></blockquote><p><strong>Chandler Bing:</strong> She gets crazy! This scar (points to his forehead) is from Pictionary!</p><blockquote><p>她疯了！这个伤疤（指向他的额头）是Picturional留下的！</p></blockquote><p><em>(Monica rolls her eyes)</em></p><blockquote><p><em>（莫妮卡转动眼睛）</em></p></blockquote><p><strong>Mike:</strong> (disbelieving) I think I will be all right! (to Monica) You wanna volley a bit for a serve?</p><blockquote><p>（不相信）我想我会没事的！（对莫妮卡）你想截击一下发球吗？</p></blockquote><p><strong>Monica Geller:</strong> Sure! Got to!</p><blockquote><p>当然！一定要！</p></blockquote><p><em>(Monica and Mike start to play ping pong. Mike scores)</em></p><blockquote><p><em>（莫妮卡和迈克开始打乒乓球，迈克得分）</em></p></blockquote><p><strong>Monica Geller:</strong> Aww!</p><blockquote><p>啊！</p></blockquote><p><strong>Mike:</strong> Oh, by the way... I&#39;m awesome!!</p><blockquote><p>噢，对了。。。我太棒了！！</p></blockquote><p><strong>Chandler Bing:</strong> (nearly whispering) Oh dear God, there&#39;s two of them!</p><blockquote><p>（几乎耳语）哦，天哪，他们有两个！</p></blockquote><p><strong>Mike:</strong> You&#39;re ready to play?</p><blockquote><p>你准备好玩了吗？</p></blockquote><p><strong>Monica Geller:</strong> Hell, yeah!</p><blockquote><p>见鬼，是的！</p></blockquote><p><strong>Chandler Bing:</strong> (to Phoebe) Did you know this about him?</p><blockquote><p>（对菲比）你知道他的事吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> No idea! I though he was soft like you!</p><blockquote><p>不知道！我以为他像你一样温柔！</p></blockquote><p><strong>Mike:</strong> Wanna make it more interesting?</p><blockquote><p>想让它更有趣吗？</p></blockquote><p><strong>Monica Geller:</strong> How much were you thinking?</p><blockquote><p>你想了多少？</p></blockquote><p><strong>Mike:</strong> Ten bucks a game?</p><blockquote><p>一场十美元？</p></blockquote><p><strong>Monica Geller:</strong> Make it fifty!</p><blockquote><p>五十吧！</p></blockquote><p><strong>Mike:</strong> I&#39;ll make it a hundred!</p><blockquote><p>我要一百元！</p></blockquote><p><strong>Monica Geller:</strong> (nearly shouting) One thousand...</p><blockquote><p>（差点喊）一千。。。</p></blockquote><p><strong>Chandler Bing:</strong> (interrupting her) OK!</p><blockquote><p>（打断她）好的！</p></blockquote><p><strong>Mike:</strong> To see who goes first, you got a quarter?</p><blockquote><p>看谁先去，你有25美分吗？</p></blockquote><p><strong>Monica Geller:</strong> (going through her pockets) No... (to Chandler and Phoebe) Either of you girls got a quarter?</p><blockquote><p>（翻她的口袋）不。。。（对钱德勒和菲比）你们两个女孩都有25美分？</p></blockquote><p><strong>Chandler Bing:</strong> Honey, try to focus the trash talk on him!</p><blockquote><p>亲爱的，试着把废话集中在他身上！</p></blockquote><p><strong>Phoebe Buffay:</strong> (picks up a coin from her bra) Monica, you call it.</p><blockquote><p>（从她的胸罩里捡起一枚硬币）莫妮卡，你叫它。</p></blockquote><p><strong>Monica Geller:</strong> Heads! No, Tails! He-he-heads!</p><blockquote><p>头！不，尾巴！他走了！</p></blockquote><p><strong>Phoebe Buffay:</strong> Tails!</p><blockquote><p>尾巴！</p></blockquote><p><strong>Monica Geller:</strong> (angry) Ow, what are the chances!</p><blockquote><p>（生气）哦，机会有多大！</p></blockquote><p><em>(They start playing again)</em></p><blockquote><p><em>（他们又开始玩了）</em></p></blockquote><p><strong>Monica Geller:</strong> Ha! My point!</p><blockquote><p>哈！我的观点！</p></blockquote><p><strong>Mike:</strong> Oh, no! I don&#39;t think so! You know, according to standard table tennis rules if at any time a player uses his non racket bearing hand to touch the playing surface he or she forfeits the point.</p><blockquote><p>哦，不！我不这么认为！你知道，根据标准的乒乓球规则，任何时候，如果一名球员用他不带球拍的手触碰比赛场地，他或她将被扣分。</p></blockquote><p><strong>Phoebe Buffay:</strong> (smiling proudly) He was a lawyer!</p><blockquote><p>（自豪地微笑）他是个律师！</p></blockquote><hr><p>🎬 <em>Rachel&#39;s hotel room. She is watching the Weather Channel on TV.</em></p><blockquote><p>🎬 <em>瑞秋的酒店房间。她正在看电视上的天气频道。</em></p></blockquote><p><strong>Alexandra Steele:</strong> (meteorologist) (pointing to the East Coast)... all these coasts having beautiful weather. In New York, it&#39;s 72 and sunny!</p><blockquote><p>（气象学家）（指着东海岸）。。。这些海岸的天气都很好。在纽约，72岁，阳光明媚！</p></blockquote><p><strong>Rachel Green:</strong> Oh! Weather bitch! (turns the TV off)</p><blockquote><p>哦！天气婊子！（关掉电视）</p></blockquote><p><em>(Someone knocks on the door)</em></p><blockquote><p><em>（有人敲门）</em></p></blockquote><p><strong>Rachel Green:</strong> It&#39;s open! (Joey walks in) Hi, Joe!</p><blockquote><p>开门了！（乔伊走进来）嗨，乔！</p></blockquote><p><strong>Joey Tribbiani:</strong> (downhearted) Hey...</p><blockquote><p>（沮丧地）嘿。。。</p></blockquote><p><strong>Rachel Green:</strong> (worried) What, is everything ok?</p><blockquote><p>（担心）什么，一切都好吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh... Charlie and I broke up.</p><blockquote><p>嗯。。。查理和我分手了。</p></blockquote><p><strong>Rachel Green:</strong> Nooooo, why?</p><blockquote><p>没有，为什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh well, she said we have nothing in common.</p><blockquote><p>哦，她说我们没有共同点。</p></blockquote><p><strong>Rachel Green:</strong> (laughing) Oh, that&#39;s crazy!</p><blockquote><p>（笑）哦，那太疯狂了！</p></blockquote><p><strong>Joey Tribbiani:</strong> No, it&#39;s not, we have nothing in common!</p><blockquote><p>不，不是，我们没有共同点！</p></blockquote><p><strong>Rachel Green:</strong> ... yeah, it&#39;s true.</p><blockquote><p>。。。是的，这是真的。</p></blockquote><p><strong>Joey Tribbiani:</strong> I mean, she should be with someone like... Ross! You know what I mean, he uses all those big words too! Man, smart people are dull!</p><blockquote><p>我是说，她应该和像。。。罗斯！你知道我的意思，他也用了这么多大字！老兄，聪明的人都很迟钝！</p></blockquote><p><strong>Rachel Green:</strong> (pretending to be offended) What, hey!</p><blockquote><p>（假装生气）什么，嘿！</p></blockquote><p><strong>Joey Tribbiani:</strong> (laughing sarcastically) Ok, Rach!</p><blockquote><p>（讽刺地笑）好的，瑞秋！</p></blockquote><p><em>(He punches her on her shoulder mockingly, then goes and sits down on her bed)</em></p><blockquote><p><em>（他嘲弄地打了她一拳，然后走到她的床上坐下）</em></p></blockquote><p><strong>Joey Tribbiani:</strong> I feel so stupid, you know? Why... why do I keep going after the wrong girls?</p><blockquote><p>我觉得自己很傻，你知道吗？为什么？为什么我总是追错女孩？</p></blockquote><p><strong>Rachel Green:</strong> W-What are you, what are you talking about?</p><blockquote><p>你在说什么，你在说什么？</p></blockquote><p><strong>Joey Tribbiani:</strong> Oh, c&#39;mon, I mean, there&#39;s you, then there&#39;s Charlie, and it&#39;s like... (sighs) What the hell is my problem? OH! (He falls back on the bed)</p><blockquote><p>哦，拜托，我是说，有你，然后是查理，就像。。。（叹气）我到底有什么问题？哦（他倒在床上）</p></blockquote><p><strong>Rachel Green:</strong> Ok... uh... maybe you&#39;re not always going after the wrong girl...</p><blockquote><p>好的。。。UH也许你不是一直在追求错误的女孩。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> (sitting up again) I&#39;m telling you, Rach, Charlie is not right for me!</p><blockquote><p>（又坐起来）我告诉你，瑞秋，查理不适合我！</p></blockquote><p><strong>Rachel Green:</strong> Yeah, I&#39;m not talking about her...</p><blockquote><p>是啊，我不是在说她。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> But then who? The waitress I went out with last month? (gives her a meaningful look)</p><blockquote><p>那又是谁呢？上个月和我约会的那个女服务员？（意味深长地看了她一眼）</p></blockquote><p><strong>Rachel Green:</strong> You know? Forget it!</p><blockquote><p>你知道吗？算了吧！</p></blockquote><p><strong>Joey Tribbiani:</strong> (stands up) No-no-no-no, no! Who, who were you talking about?</p><blockquote><p>（站起来）不，不，不！你在说谁？</p></blockquote><p><strong>Rachel Green:</strong> No, I-I-I-I don&#39;t, I actually don&#39;t know who I&#39;m talking about! So!</p><blockquote><p>不，我不知道，我真的不知道我在说谁！所以</p></blockquote><p><strong>Joey Tribbiani:</strong> Ok! All right, well... I&#39;m gonna see if I can get a room for the night and I&#39;ll... I&#39;ll see you later!</p><blockquote><p>好的！好吧，好吧。。。我去看看能不能弄到一个房间过夜我会。。。回头见！</p></blockquote><p><strong>Rachel Green:</strong> Yeah, sure!</p><blockquote><p>是的，当然！</p></blockquote><p><em>(Joey walks out, while Rachel is pensive. Once he&#39;s out of her room, he suddenly realizes who she was talking about and goes back in. He looks at her in disbelief and she looks like she was caught red-handed)</em></p><blockquote><p><em>（乔伊走了出去，瑞秋正在沉思。他一走出她的房间，就突然意识到她在说谁，然后又走了进去。他难以置信地看着她，她看起来像是被当场抓住了）</em></p></blockquote><hr><p>🎬 <em>Rachel&#39;s hotel room. Joey is standing at the door, facing Rachel</em></p><blockquote><p>🎬 <em>瑞秋的酒店房间。乔伊站在门口，面对瑞秋</em></p></blockquote><p><strong>Joey Tribbiani:</strong> You like me? (shuts the door)</p><blockquote><p>你喜欢我吗？（关上门）</p></blockquote><p><strong>Rachel Green:</strong> (nearly whispering) Ok, let&#39;s not make a big thing about this!</p><blockquote><p>（几乎耳语）好吧，我们不要把这件事说得太过分了！</p></blockquote><p><strong>Joey Tribbiani:</strong> (shocked) That&#39;s a huge thing!</p><blockquote><p>（震惊）这是件大事！</p></blockquote><p><strong>Rachel Green:</strong> Not working with me, Joe! Here&#39;s the thing: lately I have been having thoughts (pauses) musings, if you will!</p><blockquote><p>乔，不是和我一起工作！事情是这样的：最近我一直在思考（暂停）沉思，如果你愿意的话！</p></blockquote><p><strong>Joey Tribbiani:</strong> What... for how long?</p><blockquote><p>什么。。。要多久？</p></blockquote><p><strong>Rachel Green:</strong> Only like a month!</p><blockquote><p>就一个月！</p></blockquote><p><strong>Joey Tribbiani:</strong> (outraged) A MONTH??</p><blockquote><p>（愤怒）一个月？？</p></blockquote><p><strong>Rachel Green:</strong> What the... DIAL IT DOWN! (Joey goes to sit on the bed) Listen, ok, and maybe they&#39;re crazy thoughts, but sometimes I do, I have, I&#39;ve been thinking about... you know, us! (looks at Joey, who&#39;s totally distraught) Ok, dial it up a little!</p><blockquote><p>什么。。。把它拨下来！（乔伊去坐在床上）听着，好吧，也许它们是疯狂的想法，但有时我会，我有，我一直在想。。。你知道，我们！（看着乔伊，他完全心烦意乱）好了，拨大一点！</p></blockquote><p><strong>Joey Tribbiani:</strong> (stands up) I just have one question!</p><blockquote><p>（站起来）我只有一个问题！</p></blockquote><p><strong>Rachel Green:</strong> Shoot!</p><blockquote><p>开枪！</p></blockquote><p><strong>Joey Tribbiani:</strong> (desperate) What the hell are you doin&#39;???</p><blockquote><p>（绝望）你到底在干什么？？？</p></blockquote><p><strong>Rachel Green:</strong> I don&#39;t know, I&#39;m not trying to do anything, it&#39;s just, we have such a good time when we&#39;re together, you know... I mean, aren&#39;t you just a... little curious... (insinuating) what that would be like?...</p><blockquote><p>我不知道，我什么都不想做，只是，我们在一起的时候很开心，你知道。。。我是说，你不只是一个。。。有点好奇。。。（影射）那会是什么样子？。。。</p></blockquote><p><strong>Joey Tribbiani:</strong> Uh, am I curious? I mean, I am as curious as... as... George!!</p><blockquote><p>呃，我好奇吗？我的意思是，我和。。。作为。。。乔治！！</p></blockquote><p><strong>Rachel Green:</strong> (puzzled) Who...?</p><blockquote><p>（困惑地）谁。。。？</p></blockquote><p><strong>Joey Tribbiani:</strong> CURIOUS GEORGE (see link)! You know, the monkey, and the guy with the yellow hat!</p><blockquote><p>好奇的乔治（见链接）！你知道，猴子和戴黄帽子的家伙！</p></blockquote><p><strong>Rachel Green:</strong> Oh yes, of course, I remember him!</p><blockquote><p>哦，是的，当然，我记得他！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah, he had a paper route.</p><blockquote><p>是的，他有一条送报路线。</p></blockquote><p><strong>Rachel Green:</strong> Yeah, he did! (smiling) Oh, see, this is what I&#39;m talking about!</p><blockquote><p>是的，他做到了！（微笑）哦，看，这就是我说的！</p></blockquote><p><strong>Joey Tribbiani:</strong> No, I know, yeah I know we&#39;re great but Rach no... this... this can&#39;t happen!</p><blockquote><p>不，我知道，是的，我知道我们很棒，但瑞秋不。。。这这不可能发生！</p></blockquote><p><strong>Rachel Green:</strong> But can it... just... happen a little bit?</p><blockquote><p>但是它能。。。只是发生一点点吗？</p></blockquote><p><strong>Joey Tribbiani:</strong> (charmed, but then recoiling) NO, NO! It can&#39;t happen at all!</p><blockquote><p>（被迷住了，但又退缩了）不，不！这根本不可能发生！</p></blockquote><p><strong>Rachel Green:</strong> But why, why not?</p><blockquote><p>但是为什么，为什么不呢？</p></blockquote><p><strong>Joey Tribbiani:</strong> Because... look, no one wants this to happen more than me, ok? (in a trembling voice) I have gone over this moment in my head a hundred times and not once did I ever say no! (sighs) I couldn&#39;t do it to Ross!</p><blockquote><p>因为。。。听着，没有人比我更希望这样，好吗？（颤抖的声音）这一刻我已经在脑子里想了一百遍了，从来没有说过一次不！（叹气）我不能这样对罗斯！</p></blockquote><p><strong>Rachel Green:</strong> But that wasn&#39;t gonna stop you before!</p><blockquote><p>但这之前并不能阻止你！</p></blockquote><p><strong>Joey Tribbiani:</strong> I know, I know! But I&#39;ve thought about it a lot since, and it just wouldn&#39;t be right... (painfully) I&#39;m sorry...!</p><blockquote><p>我知道，我知道！但从那以后我就想了很多，这是不对的。。。（痛苦地）对不起。。。！</p></blockquote><p><strong>Rachel Green:</strong> (regretful) I&#39;m sorry, too! (they look at each other sadly, then she recollects, and puts her hands over her eyes) OH GOD! I shouldn&#39;t have said anything!</p><blockquote><p>（后悔）我也很抱歉！（他们悲伤地看着对方，然后她回忆起来，把手放在眼睛上）哦，上帝！我什么都不该说！</p></blockquote><p><strong>Joey Tribbiani:</strong> NO! No-no-no-no-no-no! Hey! Hey, we&#39;ll be fine! Li... hey, like you said: no big deal!</p><blockquote><p>不！不不不不！嘿嘿，我们会没事的！锂。。。嘿，就像你说的：没什么大不了的！</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s not a big deal!</p><blockquote><p>没什么大不了的！</p></blockquote><p><strong>Joey Tribbiani:</strong> NO BIG DEAL!</p><blockquote><p>没什么大不了的！</p></blockquote><p><strong>Rachel Green:</strong> It&#39;s so not a big deal!</p><blockquote><p>没什么大不了的！</p></blockquote><p><strong>Joey Tribbiani:</strong> Yeah! I&#39;ll see ya later! Yeah!</p><blockquote><p>是啊！回头见！是 啊</p></blockquote><p><strong>Rachel Green:</strong> Ok!</p><blockquote><p>好的！</p></blockquote><p><em>(They shake hands, he walks out and shuts the door, then seems to change his mind, moves to open the door, than changes his mind again and leans over the door. Just then, Rachel opens the door)</em></p><blockquote><p><em>（他们握了握手，他走出去关上门，然后似乎改变了主意，开始开门，然后又改变了主意，斜靠在门上。就在这时，瑞秋打开了门）</em></p></blockquote><p><strong>Rachel Green:</strong> Ok, I...</p><blockquote><p>好的，我。。。</p></blockquote><p><em>(Joey falls backwards into the room)</em></p><blockquote><p><em>（乔伊倒进了房间）</em></p></blockquote><p><strong>Rachel Green:</strong> AAAHHHH!</p><blockquote><p>啊！</p></blockquote><p><em>(Joey hurriedly stands up, arms akimbo, gives her an embarrassed look and walks away)</em></p><blockquote><p><em>（乔伊赶紧站起来，抱着阿金博，尴尬地看了她一眼，然后走开了）</em></p></blockquote><hr><p>🎬 <em>the hotel game room. Monica and Mike are still playing ping pong</em></p><blockquote><p>🎬 <em>酒店游戏室。莫妮卡和迈克还在打乒乓球</em></p></blockquote><p><strong>Monica Geller:</strong> Ooh! I&#39;m sorry! I think, I THINK, that may have missed the table!</p><blockquote><p>哦！我很抱歉！我想，我想，那可能错过了桌子！</p></blockquote><p><strong>Mike:</strong> Do you?</p><blockquote><p>是吗？</p></blockquote><p><strong>Monica Geller:</strong> Ah, yeah!</p><blockquote><p>啊，是的！</p></blockquote><p><strong>Mike:</strong> Do you?</p><blockquote><p>是吗？</p></blockquote><p><strong>Monica Geller:</strong> Ah, yeaaah!</p><blockquote><p>啊，是啊！</p></blockquote><p><strong>Mike:</strong> DO YOU?</p><blockquote><p>是吗？</p></blockquote><p><strong>Monica Geller:</strong> AH YEAAAAH!</p><blockquote><p>啊，是啊！</p></blockquote><p><strong>Chandler Bing:</strong> (to Phoebe) Do you really find this attractive on him?</p><blockquote><p>（对菲比）你真的觉得这对他有吸引力吗？</p></blockquote><p><strong>Phoebe Buffay:</strong> (looking at Mike) Oh, yeah! (turning to Chandler) Are you telling me you... you&#39;re not even... a little turned on by Monica, right now?</p><blockquote><p>（看着迈克）哦，是的！（转向钱德勒）你是在告诉我你。。。你甚至不。。。莫妮卡有点激动，现在？</p></blockquote><p><em>(Chandler turns to look at Monica, who has the biggest hair ever, is flushed and in a sweat, and is decidedly sniffing her armpits)</em></p><blockquote><p><em>（钱德勒转过身来，看着莫妮卡，她有着史上最大的头发，满脸通红，满身大汗，还断然地嗅着她的腋窝）</em></p></blockquote><p><strong>Chandler Bing:</strong> I think this is the first time in our marriage that I&#39;ve felt like the more attractive one.</p><blockquote><p>我想这是我们婚姻中我第一次觉得自己更有魅力。</p></blockquote><p><strong>Phoebe Buffay:</strong> C&#39;mon Mike, you can beat her! Knock that dog off her head!</p><blockquote><p>来吧，迈克，你可以打败她！把那条狗从她头上打掉！</p></blockquote><p><em>(Mike scores)</em></p><blockquote><p><em>（迈克得分）</em></p></blockquote><p><strong>Monica Geller:</strong> Oh, damn it!</p><blockquote><p>哦，该死！</p></blockquote><p><strong>Phoebe Buffay:</strong> (pointing at Mike and shouting) I sleep with him!</p><blockquote><p>（指着迈克喊道）我和他睡觉了！</p></blockquote><p><strong>Mike:</strong> (boasting) Game, point!</p><blockquote><p>（自夸）游戏，得分！</p></blockquote><p><strong>Monica Geller:</strong> (threatening) Don&#39;t get too cocky! Remember I won the last one! Oh, by the way, how did that feel, losing to a girl?</p><blockquote><p>（威胁）不要太自大！记得上次我赢了！哦，顺便问一下，输给一个女孩感觉如何？</p></blockquote><p><strong>Mike:</strong> You know, you should really look in a mirror before you call yourself that.</p><blockquote><p>你知道，在你这么称呼自己之前，你应该先照镜子。</p></blockquote><p><em>(they continue to play ping pong and then Mike scores, winning the game)</em></p><blockquote><p><em>（他们继续打乒乓球，然后迈克得分，赢得了比赛）</em></p></blockquote><p><strong>Monica Geller:</strong> NO, NO, NOOO!</p><blockquote><p>不，不，不！</p></blockquote><p><strong>Mike:</strong> And that&#39;s how it&#39;s done! (Phoebe kisses him)</p><blockquote><p>就是这样做的！（菲比吻了他）</p></blockquote><p><strong>Chandler Bing:</strong> Okay-dokay, you&#39;ve each won a game and I&#39;ve lost what&#39;s felt like a year of my life. So everybody goes home a winner.</p><blockquote><p>好吧，多凯，你们每个人都赢了一场比赛，而我却失去了我生命中的一年。所以每个人回家都是赢家。</p></blockquote><p><strong>Monica Geller:</strong> Best out of three?</p><blockquote><p>三局中最好的？</p></blockquote><p><strong>Mike:</strong> That&#39;s what I&#39;m thinking.</p><blockquote><p>我就是这么想的。</p></blockquote><p><strong>Chandler Bing:</strong> Should I use my invisibility to fight crime or for evil?</p><blockquote><p>我应该用我的隐形来打击犯罪还是作恶？</p></blockquote><p><strong>Monica Geller:</strong> (to Mike) Serve the ball, chump!</p><blockquote><p>（对迈克）发球，笨蛋！</p></blockquote><p><strong>Mike:</strong> (doing Monica and mumbling): Serve the ball, chump.</p><blockquote><p>（做莫妮卡和咕哝）：发球，笨蛋。</p></blockquote><p><strong>Phoebe Buffay:</strong> (to Mike) Ok Mike, better come back Mike, better come back.</p><blockquote><p>（对迈克）好的，迈克，最好回来，迈克，最好回来。</p></blockquote><hr><p>🎬 <em>hotel&#39;s bar, Ross and Mr. Oberblau are talking</em></p><blockquote><p>🎬 <em>酒店的酒吧，罗斯和奥伯布鲁先生正在交谈</em></p></blockquote><p>Mr. Oberblau: I&#39;m just saying, I have a cabin in the Adirondacks if you ever want to get away from the city, well, that&#39;d be (pause) just nifty!</p><blockquote><p>我只是说，如果你想离开这个城市，我在阿迪朗达克有一间小木屋，嗯，那（暂停）真是太好了！</p></blockquote><p><strong>Ross Geller:</strong> Ooh, well. Ah, I kinda have got a lot on my plate right now, not that I wouldn&#39;t love a weekend in the country with a strange man. (Mr. Oberblau giggles)</p><blockquote><p>哦，好吧。啊，我现在有很多事情要做，并不是说我不喜欢和一个陌生男人在乡下度周末。（奥博布劳先生咯咯笑着）</p></blockquote><p><strong>Woman:</strong> Jarvis?</p><blockquote><p>贾维斯？</p></blockquote><p>Mr. Oberblau: (seeing her) Oh, you&#39;re back... (to Ross) this is my wife, Nancy.</p><blockquote><p>（看到她）哦，你回来了。。。（对罗斯）这是我妻子南希。</p></blockquote><p><strong>Ross Geller:</strong> Get Out!</p><blockquote><p>出去！</p></blockquote><p><em>(Charlie walks by)</em></p><blockquote><p><em>（查理走过）</em></p></blockquote><p><strong>Charlie:</strong> Ross, can I talk to you for a minute?</p><blockquote><p>罗斯，我能和你谈谈吗？</p></blockquote><p><strong>Ross Geller:</strong> Yes, please! (they move and sit down on a sofa) So, what&#39;s going on?</p><blockquote><p>是的，谢谢！（他们移动并坐在沙发上）那么，发生了什么事？</p></blockquote><p><strong>Charlie:</strong> Uh, well... Joey and I broke up.</p><blockquote><p>嗯，嗯。。。乔伊和我分手了。</p></blockquote><p><strong>Ross Geller:</strong> Oh my God, wh-what happened?</p><blockquote><p>天啊，发生什么事了？</p></blockquote><p><strong>Charlie:</strong> Joey is a great guy, but we&#39;re just... so different! I mean, during your speech he kept laughing at homo erectus!</p><blockquote><p>乔伊是个很棒的人，但我们只是。。。太不一样了！我是说，在你的演讲中，他一直在嘲笑直立人！</p></blockquote><p><strong>Ross Geller:</strong> I knew that was him!</p><blockquote><p>我就知道是他！</p></blockquote><p><strong>Charlie:</strong> Anyway I just, uh, I think it&#39;s for the best.</p><blockquote><p>不管怎样，我只是，嗯，我认为这是最好的。</p></blockquote><p><strong>Ross Geller:</strong> (holding her hand) Hey, you ok?</p><blockquote><p>（握住她的手）嘿，你还好吗？</p></blockquote><p><strong>Charlie:</strong> I guess. There was hum... (she breathes deeply) there was another reason that I thought it was time to end it with Joey. I started to realize that I was having feelings for someone (pause) else.</p><blockquote><p>我想是吧。有嗡嗡声。。。（她深深地吸了一口气）还有一个原因，我认为是时候和乔伊结束这一切了。我开始意识到我对别人有感情（停顿）。</p></blockquote><p><em>(some paleontologists interrupt them)</em></p><blockquote><p><em>（一些古生物学家打断了他们）</em></p></blockquote><p><strong>Paleontologist:</strong> (merrily) Ok Geller. Last day of the conference, you know what happens to the keynote speaker.</p><blockquote><p>（高兴地）好的，盖勒。会议的最后一天，你知道主旨发言人会发生什么。</p></blockquote><p><strong>Ross Geller:</strong> Oh, professor Clerk we&#39;re kind of in the middle of a conversation, here.</p><blockquote><p>噢，教授，我们有点谈话，在这里。</p></blockquote><p><strong>Charlie:</strong> Yeah, can you guys just throw him in the pool later?</p><blockquote><p>是啊，你们能等会儿把他扔到游泳池里吗？</p></blockquote><p><strong>Professore Clerk:</strong> Or we could throw you both in now!</p><blockquote><p>或者我们现在就把你们两个都扔进去！</p></blockquote><p><strong>Ross Geller:</strong> (standing) Ok, gentlemen! Please! Aren&#39;t we a little old for this? I mean, we&#39;re scientists, right? We&#39;re academics. And most importantly I... you-you will have to catch us first. (he starts to run away with Charlie). GO, GO, GO! (the paleontologists starts chasing them)</p><blockquote><p>（站着）好的，先生们！请我们不是有点老了吗？我是说，我们是科学家，对吗？我们是学者。最重要的是我。。。你得先抓住我们。（他开始和查理私奔）。走，走，走！（古生物学家开始追踪它们）</p></blockquote><hr><p>🎬 <em>game room, Monica and Mike are still playing ping pong</em></p><blockquote><p>🎬 <em>游戏室，莫妮卡和迈克还在打乒乓球</em></p></blockquote><p><em>(Chandler and Phoebe look bored to death. Monica scores and laughs)</em></p><blockquote><p><em>（钱德勒和菲比看起来无聊得要死。莫妮卡得分并大笑）</em></p></blockquote><p><strong>Mike:</strong> Ok, so it&#39;s a tie again, 41 to 41.</p><blockquote><p>好吧，又是平局了，41比41。</p></blockquote><p><strong>Chandler Bing:</strong> (exhausted) Ok, look! Enough is enough!</p><blockquote><p>（筋疲力尽）好的，看！适可而止</p></blockquote><p><strong>Monica Geller:</strong> No, I have just to have two more points to beat him!</p><blockquote><p>不，我只要再得两分就可以打败他！</p></blockquote><p><strong>Chandler Bing:</strong> Monica, that was also true an hour ago! I mean, please, look at you! Your hand is blistered, you can barely stand, your hair is inexplicable! Ok, you&#39;ve already proven you are just as good as he is, now we&#39;ve missed our dinner reservations, so now let&#39;s just go upstairs, order room service, take a shower and shave your head!</p><blockquote><p>莫妮卡，一小时前也是这样！我是说，拜托，看看你！你的手起了水泡，你几乎站不住，你的头发令人费解！好吧，你已经证明了你和他一样好，现在我们错过了晚餐预定，所以现在我们上楼，点客房服务，冲个澡，剃个光头吧！</p></blockquote><p><strong>Monica Geller:</strong> I can&#39;t just walk away! I&#39;ve put in four hours!</p><blockquote><p>我不能就这么走开！我已经投入了四个小时！</p></blockquote><p><strong>Chandler Bing:</strong> But...</p><blockquote><p>但是。。。</p></blockquote><p><strong>Monica Geller:</strong> Look! You knew this about me when you married me! You agreed to take me in sickness and in health. Well, this is my sickness!</p><blockquote><p>看！你嫁给我的时候就知道这件事！你同意带我去生病和健康的地方。这是我的病！</p></blockquote><p><strong>Chandler Bing:</strong> What about the obsessive cleaning?</p><blockquote><p>那强迫性的清洁呢？</p></blockquote><p><strong>Monica Geller:</strong> That&#39;s just good sense!</p><blockquote><p>这是很有道理的！</p></blockquote><p><em>(they start playing again; suddenly Monica hits the table with her hand)</em></p><blockquote><p><em>（他们又开始玩了；莫妮卡突然用手拍桌子）</em></p></blockquote><p><strong>Monica Geller:</strong> (in pain) Aww! (she holds her hand, moaning like she&#39;s biting back a scream)</p><blockquote><p>（痛苦地）啊！（她握着她的手，呻吟着，好像在回咬一声尖叫）</p></blockquote><p><strong>Chandler Bing:</strong> You ok?</p><blockquote><p>你还好吗？</p></blockquote><p><strong>Monica Geller:</strong> No, no, no. Honey, I&#39;m ok. Shake it off! (she shakes the wrist and it&#39;s more painful) Oh, no! No shaking, no shaking! Ooh! Ooh! (pause) Oh my God! I can&#39;t play!</p><blockquote><p>不，不，不。亲爱的，我没事。甩掉它！（她摇了摇手腕，更疼）哦，不！不要摇晃，不要摇晃！哦！哦！（停顿）哦，我的上帝！我不能玩！</p></blockquote><p><strong>Mike:</strong> So you forfeit?</p><blockquote><p>那么你被没收了？</p></blockquote><p><strong>Phoebe Buffay:</strong> Mike wins?</p><blockquote><p>迈克赢了？</p></blockquote><p><strong>Monica Geller:</strong> I can&#39;t believe it! (pause) I lost!</p><blockquote><p>真不敢相信！（停顿）我输了！</p></blockquote><p><strong>Chandler Bing:</strong> No, you didn&#39;t.</p><blockquote><p>不，你没有。</p></blockquote><p><strong>Monica Geller:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><strong>Chandler Bing:</strong> Because I&#39;m gonna play for ya.</p><blockquote><p>因为我要为你演奏。</p></blockquote><p><strong>Phoebe Buffay:</strong> You can&#39;t do that!</p><blockquote><p>你不能那样做！</p></blockquote><p><strong>Mike:</strong> Oh, that&#39;s ok. I don&#39;t care which of them I beat.</p><blockquote><p>哦，没关系。我不在乎我打败了谁。</p></blockquote><p><strong>Phoebe Buffay:</strong> Ok, we&#39;re taking that paddle home, mister.</p><blockquote><p>好的，我们要把桨带回家，先生。</p></blockquote><p><strong>Monica Geller:</strong> (to Chandler) Honey, you don&#39;t have to do this.</p><blockquote><p>（对钱德勒）亲爱的，你不必这么做。</p></blockquote><p><strong>Chandler Bing:</strong> (In a loving voice) Yes, I do. Now, I may not understand why you have to win so badly, but if it&#39;s important to you then it&#39;s important to me, because I love you.</p><blockquote><p>（用充满爱意的声音）是的，我喜欢。现在，我可能不明白你为什么要赢得这么惨，但如果这对你很重要，那么对我也很重要，因为我爱你。</p></blockquote><p><strong>Monica Geller:</strong> But... you suck!</p><blockquote><p>但是。。。你真烂！</p></blockquote><p><strong>Chandler Bing:</strong> (Still in a loving voice) You&#39;re welcome, sweetheart.</p><blockquote><p>（仍然用爱的声音）不客气，甜心。</p></blockquote><p><em>(Chandler prepares to play)</em></p><blockquote><p><em>（钱德勒准备上场）</em></p></blockquote><p><strong>Chandler Bing:</strong> All right Mike, let&#39;s get this over with. Sudden death. Whoever wins this point, wins.</p><blockquote><p>好吧，迈克，让我们结束这一切。突然死亡。谁赢了这一分，谁就赢。</p></blockquote><p><strong>Mike:</strong> Ok!</p><blockquote><p>好的！</p></blockquote><p><em>(They start playing and Chandler does not suck at all)</em></p><blockquote><p><em>（他们开始玩，钱德勒一点也不差劲）</em></p></blockquote><p><strong>Monica Geller:</strong> Oh my God! You&#39;re good!</p><blockquote><p>哦，我的天啊！你很好！</p></blockquote><p><strong>Phoebe Buffay:</strong> It&#39;s like watching porn!</p><blockquote><p>这就像看色情片！</p></blockquote><p><em>(Chandler scores and wins the match)</em></p><blockquote><p><em>（钱德勒得分并赢得比赛）</em></p></blockquote><p><strong>Chandler Bing:</strong> And that&#39;s... how... it&#39;s done!</p><blockquote><p>那是。。。怎样。。。完成了！</p></blockquote><p><strong>Monica Geller:</strong> (to Chandler) Oh my God. That was so amazing! When did you (pause) Hold on! I almost forgot (she turns to Mike) loser! (back to Chandler) When did you stop sucking?</p><blockquote><p>（对钱德勒）哦，我的天啊。真是太神奇了！你（停顿）什么时候坚持住的！我差点忘了（她转向迈克）失败者！（回到钱德勒身边）你什么时候停止吸了？</p></blockquote><p><strong>Chandler Bing:</strong> I never sucked, I actually didn&#39;t want you to know how good I was!</p><blockquote><p>我从来没有吸过，我其实不想让你知道我有多好！</p></blockquote><p><strong>Monica Geller:</strong> Why?</p><blockquote><p>为什么？</p></blockquote><p><strong>Chandler Bing:</strong> I don&#39;t know.</p><blockquote><p>我不知道。</p></blockquote><p><strong>Monica Geller:</strong> This is so great! Now we can enter into doubles tournaments!</p><blockquote><p>这太棒了！现在我们可以参加双打比赛了！</p></blockquote><p><strong>Chandler Bing:</strong> That&#39;s why!</p><blockquote><p>这就是为什么！</p></blockquote><hr><p>🎬 <em>Hotel&#39;s bar. Ross is running to Charlie trying not to be seen with two cocktails in his hands. She&#39;s hidden behind a huge plant</em></p><blockquote><p>🎬 <em>酒店酒吧。罗斯跑向查理，试图不让人看到他手里拿着两杯鸡尾酒。她藏在一个巨大的植物后面</em></p></blockquote><p><strong>Charlie:</strong> Thanks!</p><blockquote><p>谢谢！</p></blockquote><p><strong>Ross Geller:</strong> Hi.</p><blockquote><p>嗨。</p></blockquote><p><strong>Charlie:</strong> Are they still looking for us?</p><blockquote><p>他们还在找我们吗？</p></blockquote><p><strong>Ross Geller:</strong> Yeah. The bartender said that they split up into two search parties, the herbivores and the carnivores. (pause) You know, we as a group are not the coolest.</p><blockquote><p>是的。酒保说他们分成了两个搜索小组，食草动物和食肉动物。（停顿）你知道，我们作为一个群体不是最酷的。</p></blockquote><p><em>(Three paleontologists walk by and Ross hugs Charlie trying not to be seen)</em></p><blockquote><p><em>（三位古生物学家走过，罗斯拥抱查理，尽量不让人看见）</em></p></blockquote><p><strong>Ross Geller:</strong> I don&#39;t think they saw us.</p><blockquote><p>我想他们没看见我们。</p></blockquote><p><strong>Charlie:</strong> I don&#39;t think they did.</p><blockquote><p>我想他们没有。</p></blockquote><p><em>(They realize that they are hugging closely and he draws back)</em></p><blockquote><p><em>（他们意识到他们正在紧紧拥抱，而他后退了）</em></p></blockquote><p><strong>Charlie:</strong> Hum, so, I started to say you something earlier, hum... (pause) There was another reason I realized it was time to end it with Joey. I kind of realized I... was starting to have feelings... for someone else.</p><blockquote><p>嗯，我早就开始跟你说了，嗯。。。（停顿）还有另一个原因，我意识到是时候和乔伊结束了。我意识到我。。。开始有感觉了。。。为了别人。</p></blockquote><p><strong>Ross Geller:</strong> (apparently unruffled) Oh. Can I... can I ask who?</p><blockquote><p>（显然很平静）哦。我可以吗。。。我可以问谁吗？</p></blockquote><p><strong>Charlie:</strong> I think you know.</p><blockquote><p>我想你知道。</p></blockquote><p><strong>Ross Geller:</strong> I think I know too but I&#39;ve been really wrong about this stuff in the past, so...</p><blockquote><p>我想我也知道，但我过去对这件事的看法是错误的，所以。。。</p></blockquote><p><em>(Charlie kisses Ross, they stop for a moment and then he kisses her back)</em></p><blockquote><p><em>（查理吻了罗斯，他们停了一会儿，然后他吻了吻她的后背）</em></p></blockquote><p><strong>Ross Geller:</strong> I&#39;m sorry... we... we can&#39;t.</p><blockquote><p>对不起。。。我们。。。我们不能。</p></blockquote><p><strong>Charlie:</strong> All right, all right.</p><blockquote><p>好吧，好吧。</p></blockquote><p><strong>Ross Geller:</strong> I mean, you just went out with my best friend, and I just think it&#39;d be a really really bad idea. (pause) Or-or not! (they kiss passionately)</p><blockquote><p>我是说，你刚刚和我最好的朋友出去了，我只是觉得这是个非常糟糕的主意。（停顿）或不！（他们热吻）</p></blockquote><p><em>(Joey walks in and sees Ross and Charlie kissing. He gives a faint, rueful smile, then he seems to recollect something and suddenly he moves back to Rachel&#39;s room. He knocks on her door and she opens)</em></p><blockquote><p><em>（乔伊走了进来，看到罗斯和查理在接吻。他淡淡地、懊悔地笑了笑，然后他似乎想起了什么，突然他回到了瑞秋的房间。他敲了敲她的门，她打开了门）</em></p></blockquote><p><strong>Rachel Green:</strong> What?</p><blockquote><p>什么？</p></blockquote><p><em>(Joey says nothing, but enters the room and kisses her. They are kissing passionately only to stop for a brief &quot;oh&quot; from Rachel. They continue their passionate kiss and Joey closes the door with his foot and it shuts in the camera&#39;s &quot;face&quot;. And that&#39;s the end of the ninth season.)</em></p><blockquote><p><em>（乔伊一言不发，走进房间吻了她。他们热烈地接吻，只是为了让瑞秋短暂地说声“哦”。他们继续热烈的接吻，乔伊用脚把门关上，镜头的“脸”关上了。这是第九季的结束。）</em></p></blockquote><p>[1] Homo ergaster: Some scientists classify some African erectus specimens as belonging to a separate species, Homo ergaster, which differs from the Asian H. erectus fossils in some details of the skull (e.g. the brow ridges differ in shape, and erectus would have a larger brain size).</p><blockquote><p>[1] ergaster人：一些科学家将一些非洲直立人标本归类为属于一个单独的物种，即ergaster人，这与亚洲直立人化石在头骨的某些细节上有所不同（例如，额骨脊的形状不同，直立人的大脑会更大）。</p></blockquote>`,1403)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};